statement.tex:
$p>0$ とし，放物線 $C:y^2=4px$ の第1象限の部分の点 P における法線と $x$ 軸の交点を N，線分 PN の中点を M とする．
\begin{enumerate}
  \item P が $C$ 上を動くとき，M の軌跡を求めよ．
  \item (1) の軌跡（を含む放物線）の焦点の座標を求めよ．
\end{enumerate}

2点 $(0,2),(0,-2)$ を焦点とする双曲線 $C_1$ と，2点 $(1,0),(-1,0)$ を焦点とする楕円 $C_2$ は，2点 $(0,\pm1)$ のみを共有している．
\begin{enumerate}
  \item $C_1$，$C_2$ の方程式を求めよ．
  \item $C_1$ と漸近線を共有する双曲線 $C_3$ が $C_2$ とちょうど4点を共有し，その4点が正方形の頂点となるとき，$C_3$ の方程式と正方形の面積を求めよ．
\end{enumerate}

楕円 $\dfrac{x^2}{a^2}+\dfrac{y^2}{b^2}=1\ (a>0,b>0)$ と放物線 $y^2=4x$ の第1象限における交点 P での，楕円の接線を $l$，放物線の接線を $m$ とする．
\begin{enumerate}
  \item $l\perp m$ となるための $a,b$ の条件を求めよ．（P の位置によらないことに注意せよ．）
  \item (1) のとき，$l,m$ と $x$ 軸の交点をそれぞれ Q，R とする．線分 QR の長さを $a$ で表せ．
\end{enumerate}

$a>b>0$ とする．楕円 $\dfrac{x^2}{a^2}+\dfrac{y^2}{b^2}=1$ 上の点 P における接線に原点 O から下ろした垂線の足を H とする．
\begin{enumerate}
  \item P$(a\cos\theta,b\sin\theta)$ とするとき，$\text{PH}^2$ を $\theta$ で表せ．
  \item PH の最大値と，そのときの $\cos^2\theta$ の値を求めよ．
\end{enumerate}

楕円 $E:\dfrac{x^2}{4}+y^2=1$ 上の2点 P，Q と原点 O について，
\begin{enumerate}
  \item $\triangle$OPQ の面積の最大値を求めよ．
  \item $\triangle$OPQ の面積が最大となるとき，$\text{OP}^2+\text{OQ}^2$ は P，Q によらず一定であることを示せ．
\end{enumerate}

楕円 $\dfrac{x^2}4+y^2=1$ と，点 A$(1,0)$ を通る直線が2点 P，Q で交わる．
\begin{enumerate}
  \item 線分 PQ の中点 M の軌跡を求めよ．
  \item (1) の軌跡が囲む部分の面積を求めよ．
\end{enumerate}

楕円 $C:\dfrac{x^2}4+\dfrac{y^2}3=1$ の焦点 F$(1,0)$ を通り，$x$ 軸と角 $\theta$ をなす直線と $C$ の交点を P，Q とする．また F を通り PQ に垂直な直線と $C$ の交点を R，S とする．
\begin{enumerate}
  \item PQ を $\theta$ で表せ．
  \item $\dfrac1{\text{PQ}}+\dfrac1{\text{RS}}$ は $\theta$ によらない定数であることを示せ．
  \item $\text{PQ}+\text{RS}$ の最小値を求めよ．
\end{enumerate}

$xy$ 平面において，原点 O と直線 $x=3$ からの距離の比が $e:1\ (e>0)$ である点 P の軌跡を $C$ とする．
\begin{enumerate}
  \item $C$ の方程式を求めよ．
  \item $C$ が点 $(1,1)$ を通るとき，$e$ の値を求め，$C$ がどのような図形か答えよ．さらに，長軸・短軸の長さを求めよ．
\end{enumerate}

平面上の点 $(X,Y)$ を原点のまわりに $45^\circ$ 回転させた点 $(x,y)$ は $x=\frac{\sqrt2}{2}(X-Y)$，$y=\frac{\sqrt2}2(X+Y)$ で与えられる．曲線 $A:x^2+xy+y^2=6$ について，
\begin{enumerate}
  \item $A$ を原点のまわりに $-45^\circ$ 回転させてできる曲線の方程式を求め，それがどのような曲線か答えよ．
  \item $A$ が囲む部分の面積を求めよ．
  \item $A$ 上の点で原点からの距離が最大となる点をすべて求めよ．
\end{enumerate}

\begin{enumerate}
  \item 長さ2の線分 OA を直径とする円がある．O を通る直線がこの円と O 以外の点 Q で交わるとき，半直線 OQ 上に $\text{QP}=1$，$\text{OP}>\text{OQ}$ となる点 P をとる．O を極，半直線 OA を始線として，P の軌跡の極方程式を求めよ．
  \item 極方程式 $r=\dfrac{3}{1+2\cos\theta}$（$r>0$）が表す曲線を，直交座標の方程式で表し，どのような曲線のどの部分か答えよ．
\end{enumerate}

極方程式 $r=1+\cos\theta\ (0\leqq\theta<2\pi)$ で表される曲線 $C$ を考える．
\begin{enumerate}
  \item $C$ 上の点の $y$ 座標の最大値を求めよ．
  \item 極 O を通る直線上で，偏角 $\theta$ に対応する $C$ 上の点を P，偏角 $\theta+\pi$ に対応する $C$ 上の点を P$'$ とする（$r=0$ なら P$'$ は O）．線分 PP$'$ の長さは一定であることを示せ．
  \item $C$ が囲む部分の面積を求めよ．
\end{enumerate}

$t>0$ を媒介変数とする $x=\dfrac{t^2+t+1}{t}$，$y=\dfrac{2(t^2-1)}{t}$ で表された曲線 $C$ について，
\begin{enumerate}
  \item $C$ を $x,y$ の方程式で表し，$C$ はその方程式が表す曲線のどの部分か答えよ．
  \item 2定点 F，F$'$ と $C$ 上の点 P との距離の差 $|\text{PF}-\text{PF}'|$ が一定となるような F，F$'$ の座標と，その一定値を求めよ．
\end{enumerate}

$0\leqq t\leqq\frac\pi2$ とする．点 P$(\cos t,\sin t)$ における単位円の接線を $l$ とし，$l$ 上の点で P との距離が $t$ であるもののうち，直線 OP に関して点 A$(1,0)$ と同じ側にある点を Q$(f(t),g(t))$ とする．
\begin{enumerate}
  \item $f(t)$，$g(t)$ を求めよ．
  \item $\sqrt{f'(t)^2+g'(t)^2}$ を求めよ．
  \item $t$ が $0$ から $\frac\pi2$ まで変化するとき，Q が描く曲線の長さを求めよ．
\end{enumerate}

原点 O を中心とする半径2の円 $C_0$ に，半径1の円 $C$ が外接しながらすべることなく転がる．$C$ 上に固定された点 P ははじめ $(2,0)$ にあり，$C$ の中心 Q ははじめ $(3,0)$ にある．Q が O のまわりを反時計回りに角 $\theta$ だけ回ったとする．
\begin{enumerate}
  \item $\overrightarrow{\mathrm{OQ}}$，$\overrightarrow{\mathrm{QP}}$ を $\theta$ で表せ．
  \item $0\leqq\theta\leqq2\pi$ における $\triangle$OPQ の面積の最大値を求めよ．
  \item $\theta$ が $0$ から $2\pi$ まで変化するとき，P が描く曲線の長さを求めよ．
\end{enumerate}

双曲線 $x=\dfrac4{\cos t},\ y=3\tan t\ \bigl(0<t<\frac\pi2\bigr)$ 上の点 P における接線の方向ベクトルを $\vec v=\Bigl(\dfrac{dx}{dt},\dfrac{dy}{dt}\Bigr)$ とし，F$(5,0)$，F$'(-5,0)$ とする．
\begin{enumerate}
  \item PF，PF$'$ を $t$ で表せ．
  \item $\dfrac{\overrightarrow{\mathrm{PF}}\cdot\vec v}{\text{PF}}=\dfrac{\overrightarrow{\mathrm{PF'}}\cdot\vec v}{\text{PF}'}$ を示せ．
  \item P における接線は $\angle$FPF$'$ を二等分することを示せ．
\end{enumerate}

極方程式 $r=\dfrac{6}{2+\cos\theta}$ で表される曲線 $C$ について，
\begin{enumerate}
  \item $C$ を直交座標の方程式で表せ．
  \item 極 O を通る直線と $C$ の交点を P，Q とする．$\dfrac1{\text{OP}}+\dfrac1{\text{OQ}}$ は一定であることを示せ．
  \item $\text{OP}\cdot\text{OQ}$ のとりうる値の範囲を求めよ．
\end{enumerate}

双曲線 $C:\dfrac{x^2}4-\dfrac{y^2}9=1$ 上の2点 P，Q が $\angle$POQ$=\dfrac\pi2$ を満たして動く（O は原点）．O から直線 PQ に下ろした垂線の足を H とする．
\begin{enumerate}
  \item OP$=p$，OQ$=q$ とするとき，$\dfrac1{p^2}+\dfrac1{q^2}$ は一定であることを示せ．
  \item 点 H の軌跡を求めよ．
  \item $\triangle$OPQ の面積の最小値を求めよ．
\end{enumerate}

$k>0$ とする．曲線 $C:y=\dfrac1{x^k}\ (x>0)$ と放物線 $D:y=-ax(x-b)\ (a>0,b>0)$ が $x=t$ の点で接している．
\begin{enumerate}
  \item $a,b$ を $k,t$ で表せ．
  \item $D$ と $x$ 軸で囲まれた部分の面積を $S(t)$ とする．$S(t)$ が $t$ によらない定数となる $k$ の値と，そのときの $S$ を求めよ．
\end{enumerate}

双曲線 $C:\dfrac{x^2}{a^2}-\dfrac{y^2}{b^2}=1$ とする．
\begin{enumerate}
  \item 直線 $y=mx+n\ (m\neq\pm\frac ba)$ が $C$ と2点 P$_1$，P$_2$ で交わり，2本の漸近線と Q，R で交わるとき，線分 P$_1$P$_2$ の中点と QR の中点は一致することを示せ．
  \item $C$ 上の点 P における接線と漸近線との交点を Q，R とするとき，$\triangle$OQR の面積は P によらず $ab$ であることを示せ．
\end{enumerate}

サイクロイド $C:x=t-\sin t,\ y=1-\cos t\ (0<t<2\pi)$ 上の点 P$_t$ における法線と $x$ 軸の交点を M$_t$，M$_t$ に関して P$_t$ と対称な点を Q$_t$ とする．
\begin{enumerate}
  \item M$_t$ の座標を求めよ．
  \item 線分 P$_t$Q$_t$ の長さの最大値を求めよ．
  \item $t$ が $0$ から $2\pi$ まで変化するとき，Q$_t$ が描く曲線の長さを求めよ．
\end{enumerate}

点 P$(x(t),y(t))$ が $x=\sin t,\ y=\sin3t\ (0\leqq t<2\pi)$ で動くとき，P の軌跡を $C$ とする．
\begin{enumerate}
  \item P が原点を通るときの速度ベクトルをすべて求めよ．
  \item $C$ はある関数 $y=h(x)$ のグラフの一部であることを示し，$h(x)$ と $x$ の範囲を求めよ．
  \item $C$ と $x$ 軸で囲まれた部分の面積の和を求めよ．
\end{enumerate}

\begin{enumerate}
  \item 曲線 $x=e^t\cos t,\ y=e^t\sin t\ (0\leqq t\leqq\pi)$ 上の点 P における接線と直線 OP のなす角は一定であることを示し，その角を求めよ．また，この曲線の長さを求めよ．
  \item 点 $(t\cos t,\ 3t\sin t)\ (0\leqq t\leqq\pi)$ が描く曲線と $x$ 軸で囲まれた部分の面積を求めよ．
\end{enumerate}

\begin{enumerate}
  \item 1辺の長さ4の正方形の中心を E とする．E を通り，正方形に含まれるような円の全体を考え，それらの中心が存在する範囲の面積 $S_1$ を求めよ．
  \item 定点 O を中心とする半径6の円を $F$ とし，O からの距離が2の定点を H とする．H を通り，$F$ に含まれるような円の全体を考え，それらの中心が存在する範囲の面積 $S_2$ を求めよ．
\end{enumerate}

2つの双曲線 $C:\dfrac{x^2}4-y^2=1$，$H:\dfrac{x^2}4-y^2=-1$ を考える．$H$ 上の点 P$(s,t)$ に対して，方程式 $\dfrac{s}4x-ty=1$ で定まる直線を $l$ とする．
\begin{enumerate}
  \item 直線 $l$ は点 P を通らないことを示せ．
  \item 直線 $l$ と双曲線 $C$ は異なる2点 Q，R で交わることを示し，$\triangle$PQR の重心 G の座標を $s,t$ で表せ．
  \item $\triangle$PQR の面積は P の位置によらず一定であることを示し，その値を求めよ．
\end{enumerate}

放物線 $C:y^2=4x$ の焦点 F$(1,0)$ を通り，$x$ 軸と角 $\theta\ (0<\theta<\frac\pi2)$ をなす直線と $C$ の交点を P，Q とする．また，F を通り PQ に垂直な直線と $C$ の交点を R，S とする．
\begin{enumerate}
  \item PQ を $\theta$ で表せ．
  \item $\dfrac1{\text{PQ}}+\dfrac1{\text{RS}}$ は $\theta$ によらない定数であることを示せ．
  \item $\text{PQ}+\text{RS}$ の最小値を求めよ．
\end{enumerate}

楕円 $\dfrac{x^2}4+y^2=1$ 上の点 P$(2\cos\alpha,\sin\alpha)\ \bigl(0\leqq\alpha\leqq\frac\pi2\bigr)$ に対し，線分 OP と $x$ 軸の正の部分のなす角を $\theta$ とする．
\begin{enumerate}
  \item 線分 OP の長さが $\sqrt2$ 以上となるような $\tan\theta$ の範囲を求めよ．
  \item $\alpha-\theta$ が最大となるときの $\tan\alpha$ と，そのときの $\tan(\alpha-\theta)$ を求めよ．
\end{enumerate}

楕円 $\dfrac{x^2}{a^2}+\dfrac{y^2}{b^2}=1\ (a>b>0)$ について，以下の問いに答えよ．
\begin{enumerate}
  \item 焦点の1つ F を極とし，F から $x$ 軸の正の方向へ向かう半直線を始線とする極座標で，楕円の極方程式を求めよ．
  \item F を通り，互いに $120^\circ$ の角をなす3本の半直線が楕円と交わる点を A，B，C とする．$\dfrac1{\text{FA}}+\dfrac1{\text{FB}}+\dfrac1{\text{FC}}$ は一定であることを示せ．
  \item 原点 O と楕円上の3点 P$_1$，P$_2$，P$_3$ について，半直線 OP$_1$，OP$_2$，OP$_3$ が互いに $120^\circ$ の角をなすとき，$\dfrac1{\text{OP}_1^2}+\dfrac1{\text{OP}_2^2}+\dfrac1{\text{OP}_3^2}$ は一定であることを示せ．
\end{enumerate}

$c$ を実数とする．$x$ についての2次方程式 $x^2-2x+c=0$ が2つの虚数解 $\alpha,\beta$ をもつとする．
\begin{enumerate}
  \item $c$ の範囲を求め，$\alpha,\beta$ を $c$ で表せ．
  \item 複素数平面上の3点 $\alpha,\beta,c$ が正三角形の3頂点となるような $c$ を求めよ．
  \item 3点 $\alpha,\beta,c$ が $c$ を直角の頂点とする直角三角形の3頂点となるような $c$ を求めよ．
\end{enumerate}

$\omega=\dfrac{-1+\sqrt3i}2$ とする．複素数平面上の三角形 ABC の頂点を表す複素数を $z_1,z_2,z_3$ とする．
\begin{enumerate}
  \item $z_1+\omega z_2+\omega^2z_3=0$ ならば，$\triangle$ABC は正三角形であることを示せ．
  \item $z_1=1$，$z_2=i$ で $\triangle$ABC が正三角形となる $z_3$ をすべて求めよ．
  \item (2) の正三角形の面積を求めよ．
\end{enumerate}

$z$ を絶対値が1の複素数とする．
\begin{enumerate}
  \item $z^3+z$ の実部が0となるような $z$ をすべて求めよ．
  \item $|z^2-z|=1$ となるような $z$ をすべて求めよ．
  \item $n$ を自然数とする．$|z^n-1|=1$ となるような $z$ を，すべての $n$ について合わせて得られる複素数全体を，$z=\cos2\pi x+i\sin2\pi x$（$x$ は有理数）の形で特徴づけよ．
\end{enumerate}

複素数平面上で，不等式 $2|z-1|\leqq|z-4|$ と $|z|\leqq|z-2|$ を同時に満たす点 $z$ が描く図形を $D$ とする．
\begin{enumerate}
  \item $D$ を図示せよ．
  \item $z$ が $D$ 上を動くとき，$|z-3|$ の最大値と最小値を求めよ．
  \item $D$ の面積を求めよ．
\end{enumerate}

\begin{enumerate}
  \item $\dfrac{z-2i}{z-2}$ が純虚数となる点 $z$ 全体の描く図形 $P$ を図示せよ．
  \item $z$ が $P$ 上（ただし $z\neq0$）を動くとき，$w=\dfrac1z$ の描く図形を図示せよ．
\end{enumerate}

$t$ を実数として，$z=1+ti$ が描く直線を $l$ とする．
\begin{enumerate}
  \item 複素数 $z$ が $l$ 上を動くとき，$z^2$ が表す点の軌跡 $C$ を図示し，$C$ の焦点を求めよ．
  \item 直線 $l$ を原点を中心に角 $\theta\ (0\leqq\theta<\pi)$ だけ回転移動した直線を $m$ とする．$m$ と $C$ の共有点の個数を $\theta$ の値で場合分けして求めよ．
\end{enumerate}

$a>b>0$ とし，楕円 $\dfrac{x^2}{a^2}+\dfrac{y^2}{b^2}=1$ に4点で外接する長方形を考える．
\begin{enumerate}
  \item このような長方形の4頂点は，長方形の取り方によらず一定の円の上にあることを示し，その円の方程式を求めよ．
  \item このような長方形の面積のとりうる値の範囲を求めよ．
\end{enumerate}

$x=\sqrt{\sin2t}\cos t,\ y=\sqrt{\sin2t}\sin t\ \bigl(0\leqq t\leqq\frac\pi2\bigr)$ で表される曲線を $C$ とする．
\begin{enumerate}
  \item $C$ 上の点の $y$ 座標の最大値と，そのときの $x$ を求めよ．
  \item $C$ で囲まれた図形の面積を求めよ．
\end{enumerate}

$|z|>2$ となるどのような複素数 $z$ に対しても $w=z+\dfrac1z$ とは表されない複素数 $w$ 全体の集合を $T$ とする．すなわち $T=\Bigl\{w\Bigm|w=z+\dfrac1z\text{ ならば }|z|\leqq2\Bigr\}$．
\begin{enumerate}
  \item $T$ を複素数平面上に図示せよ．
  \item $T$ に属する $w$ で $|w|$ が最大になるものを求めよ．
\end{enumerate}

複素数平面上の点 $a_1,a_2,\dots$ を $a_1=1$，$a_2=1+i$，$a_{n+2}=a_{n+1}+a_n$ で定め，$b_n=\dfrac{a_{n+1}}{a_n}$ とおく．
\begin{enumerate}
  \item 3点 $b_1,b_2,b_3$ を通る円 $C$ の中心と半径を求めよ．
  \item すべての点 $b_n$ は円 $C$ の周上にあることを示せ．
\end{enumerate}

複素数平面上で，$\triangle$ABC の頂点を表す複素数を $\alpha,\beta,\gamma$ とする．$\alpha,\beta,\gamma$ が次の3条件をみたすとする．
\begin{enumerate}
  \item[1.] $\triangle$ABC は1辺の長さ $\sqrt3$ の正三角形である．
  \item[2.] $\alpha+\beta+\gamma=3$
  \item[3.] $\alpha\beta\gamma$ の実部は $\frac32$ で，虚部は正である．
\end{enumerate}
\begin{enumerate}
  \item $z=\alpha-1$ とおいて，$\beta,\gamma$ を $z$ で表せ（$\beta$ は $\alpha$ を重心のまわりに $120^\circ$ 回転したものとする）．
  \item $\alpha,\beta,\gamma$ の偏角を求めよ．ただし $0^\circ\leqq\arg\alpha\leqq\arg\beta\leqq\arg\gamma<360^\circ$ とする．
\end{enumerate}

$a>0$ とし，$C:a^2x^2+y^2=1$，$l:y=2ax+a$ とする．
\begin{enumerate}
  \item $C$ と $l$ が異なる2点で交わる $a$ の範囲を求めよ．
  \item $C$ 上の点 $(x_0,y_0)$ における接線の方程式を求めよ．
  \item 交点 P，Q における $C$ の接線の交点を R$(X,Y)$ とする．$a$ が (1) の範囲を動くとき，$X,Y$ の関係式と $Y$ の範囲を求めよ．
\end{enumerate}

楕円 $\dfrac{x^2}{a^2}+\dfrac{y^2}{b^2}=1\ (a>b>0)$ 上の第2象限の点 P における接線を $l$，原点 O を通り $l$ に平行な直線を $m$ とし，$m$ と楕円の交点のうち第1象限のものを A とする．P を通り $m$ に垂直な直線と $m$ の交点を B とする．焦点を F$(c,0)$，F$'(-c,0)$（$c>0$）とし，直線 FP，F$'$P と $m$ の交点をそれぞれ C，C$'$ とする．
\begin{enumerate}
  \item $\text{OA}^2+\text{OP}^2=a^2+b^2$ を示せ．
  \item $\text{OA}\cdot\text{PB}=ab$ を示せ．
  \item $\text{PC}=\text{PC}'=a$ を示せ．
\end{enumerate}

\begin{enumerate}
  \item 動点 P$(x,y)$ と点 F$(0,\sqrt{10})$ との距離が，P と直線 $y=\dfrac9{\sqrt{10}}$ との距離の $\dfrac{\sqrt{10}}3$ 倍に等しいとき，P の軌跡は双曲線であることを示し，その漸近線を求めよ．
  \item (1) の双曲線上の任意の点における接線が漸近線と交わる点を Q，R とする．$\triangle$OQR の面積は一定であることを示し，その値を求めよ．
\end{enumerate}

$0<a<1$ とし，$C:(x^2+y^2-ax)^2=x^2+y^2$ を考える．
\begin{enumerate}
  \item $C$ の極方程式を求めよ（$r>0$ の形で）．
  \item $C$ と $x$ 軸，$y$ 軸の交点を求めよ．
  \item $a=\frac12$ のとき，$C$ 上の点の $x$ 座標の最大値・最小値，$y$ 座標の最大値・最小値を求めよ．
\end{enumerate}

2次曲線 $C:5x^2-2\sqrt3xy+7y^2=16$ について，
\begin{enumerate}
  \item $C$ を原点のまわりに角 $\theta\ \bigl(0\leqq\theta\leqq\frac\pi2\bigr)$ だけ回転すると $ax^2+by^2=1$ の形になる．$\theta$，$a$，$b$ を求めよ．
  \item 曲線 $C$ 上の点と点 $\bigl(c,\frac c{\sqrt3}\bigr)$ との距離の最小値が2であるとき，$c$ の値を求めよ（$c>0$）．
\end{enumerate}

$\omega=\cos\dfrac{2\pi}5+i\sin\dfrac{2\pi}5$ とする．
\begin{enumerate}
  \item $z^5=1$ の解を極形式で表せ．
  \item $t=z+\frac1z$（$z\neq1$）のとりうる値を求め，$\cos\dfrac\pi5$ を求めよ．
  \item $\displaystyle\prod_{k=1}^4(2-\omega^k)$，$\displaystyle\prod_{k=1}^4|1-\omega^k|$ を求めよ．
\end{enumerate}

$\alpha=1+\sqrt3i$ とし，$z_1=0$，$z_2=1$，$z_{n+2}=(1+\alpha)z_{n+1}-\alpha z_n$ で複素数列を定める．
\begin{enumerate}
  \item $z_n$ を $\alpha$ で表せ．
  \item $|z_n|\leqq10$ となる最大の $n$ を求めよ．
  \item $z_n$ が実数となる $n$ をすべて求めよ．
\end{enumerate}

\begin{enumerate}
  \item $\dfrac1{z+1}+\dfrac1{z-1}$ が純虚数または0となる点 $z$ 全体の図形 $P$ を図示せよ．
  \item $z$ が $P$ 上を動くとき，$w=\dfrac{z+1}{z-1}$ の描く図形を図示せよ．
\end{enumerate}

0でない複素数からなる有限集合 $G$ は，「$G$ の任意の要素 $z,w$ の積 $zw$ は再び $G$ の要素である」をみたすとする．$n$ を正の整数とし，$G$ はちょうど $n$ 個の要素からなるとする．
\begin{enumerate}
  \item $G$ の任意の要素 $z$ について $|z|=1$ を示せ．
  \item $G$ の任意の要素 $z$ について $z^n=1$ を示せ．
  \item $G=\{z\mid z^n=1\}$ であることを示せ．
\end{enumerate}

楕円 $\dfrac{x^2}9+\dfrac{y^2}5=1$ の焦点を F$(2,0)$，F$'(-2,0)$ とし，第1象限にある楕円上の点を P とする．OP$=r$ とおくとき，
\begin{enumerate}
  \item PF$^2+$PF$'^2$ および積 PF$\cdot$PF$'$ を $r$ で表せ．
  \item $\angle$F$'$PF$=\dfrac\pi3$ のとき，$r^2$ の値と点 P の座標を求めよ．
  \item (2) のとき，$\triangle$PF$'$F の面積を2通りに求めて一致することを確かめよ．
\end{enumerate}

F，F$'$ を焦点とする楕円 $\dfrac{x^2}9+\dfrac{y^2}5=1$ 上に点 P$(x_0,y_0)$（$x_0>0,\ y_0>0$）をとり，P における法線が $x$ 軸と交わる点を Q とする．
\begin{enumerate}
  \item P での法線の傾きを $x_0,y_0$ で表せ．
  \item 点 Q の $x$ 座標を $x_0$ で表し，Q が線分 FF$'$ 上にあることを示せ．
  \item PF，PF$'$ を $x_0$ で表し，FQ$:$QF$'=$PF$:$PF$'$ を示せ．これにより，法線 PQ が $\angle$FPF$'$ を二等分することを示せ．
\end{enumerate}

楕円 $\dfrac{x^2}9+y^2=1$ の第1象限にある点 P$(3\cos\theta,\sin\theta)$（$0<\theta<\frac\pi2$）における接線と $x$ 軸，$y$ 軸との交点をそれぞれ A，B とする．
\begin{enumerate}
  \item A，B の座標を $\theta$ で表せ．
  \item $\triangle$OAB の面積の最小値と，そのときの P の座標を求めよ．
  \item 線分 AB の長さの最小値と，そのときの P の座標を求めよ．
\end{enumerate}

双曲線 $C:\ \dfrac{x^2}4-y^2=1$ と，$C$ 上にない点 P$(p,q)$ を考える．
\begin{enumerate}
  \item 傾き $m$ の直線 $y=mx+n$ が $C$ に接するための条件を求めよ．
  \item P を通る $C$ の接線の傾き $m_1,m_2$（$p^2\neq4$）について，$m_1+m_2$ と $m_1m_2$ を $p,q$ で表せ．
  \item $C$ の2本の接線が直交するとき，その交点の軌跡を求めよ．
\end{enumerate}

曲線 $C:\ \dfrac{x^2}9+\dfrac{y^2}4=1$（$y\geqq0$）上に2点 A$\left(-\frac32,\sqrt3\right)$，B$(3,0)$ をとる．曲線 $C$ 上の動点 P$(3\sin\theta,2\cos\theta)$（$-\frac\pi6<\theta<\frac\pi2$）に対し，曲線 $C$ と線分 AP で囲まれる部分の面積を $S_1$，曲線 $C$ と線分 BP で囲まれる部分の面積を $S_2$ とする．
\begin{enumerate}
  \item $S_1$ と $S_2$ を $\theta$ を用いて表せ．
  \item 面積の和 $S=S_1+S_2$ を最小とする点 P の座標と $S$ の最小値を求めよ．
\end{enumerate}

\begin{enumerate}
  \item 三角方程式 $a\cos\theta+b\sin\theta=c$ が解をもつために，定数 $a,b,c$ が満たすべき必要十分条件を求めよ．
  \item $xy$ 平面上に円 $C:\ x^2+y^2=4$ と点 A$(0,1)$ がある．$C$ 上に点 P をとり，P を通って AP に垂直な直線を $l$ とする．P が $C$ 上を動くときに $l$ の通過する領域を $D$ とおく．
  \begin{enumerate}
    \item[(i)] $D$ はある楕円の周および外部であることを示せ．またこの楕円の焦点を求めよ．
    \item[(ii)] $C$ の周および内部からなる領域を $E$ とおく．領域 $D$ と $E$ の共通部分の面積を求めよ．
  \end{enumerate}
\end{enumerate}

原点で交わる2直線 $y=\sqrt3x$，$y=-\sqrt3x$ を漸近線とし，$(4,0)$，$(-4,0)$ を焦点とする双曲線を求めよう．
\begin{enumerate}
  \item 2直線をまとめて $px^2-y^2=0$ の形で表せ．
  \item 焦点 $(4,0)$ から漸近線 $y=\sqrt3x$ へ下ろした垂線の足 P の座標と，OP，焦点と P の距離を求めよ．
  \item 求める双曲線の方程式を求めよ．
\end{enumerate}

楕円 $C_0:\ \dfrac{x^2}6+\dfrac{y^2}2=1$ について，
\begin{enumerate}
  \item $C_0$ の焦点を求めよ．また，双曲線 $C_1:\ \dfrac{x^2}{k}-\dfrac{y^2}2=1$ が $C_0$ と同一の焦点をもつとき $k$ を求めよ．
  \item $C_0$ と $C_1$ の第1象限での交点 P を求め，P における $C_0$，$C_1$ の接線の傾きを求めよ．
  \item 点 Q$\left(2,\frac{\sqrt6}3\right)$ における $C_0$ の接線と，Q における双曲線 $\dfrac{x^2}{\alpha}-\dfrac{y^2}{\beta}=1$（$\alpha>0,\beta>0$）の接線が直交するという．この双曲線も $C_0$ と同一の焦点をもつとして，$\alpha,\beta$ を求めよ．
\end{enumerate}

\begin{enumerate}
  \item 正接の加法定理を用いて，2直線 $y=m_1x+b_1$ と $y=m_2x+b_2$ のなす角が $60^\circ$ ならば $\left(\dfrac{m_1-m_2}{1+m_1m_2}\right)^2=3$ が成り立つことを示せ（$1+m_1m_2\neq0$）．
  \item 放物線 $y=x^2+\dfrac14$ を $C$ とし，P，Q を $C$ 上の2点とする．P における接線と Q における接線の交点を R とする．2接線のなす角が $60^\circ$ ならば，R は双曲線 $9\left(y+\dfrac16\right)^2-3x^2=1$ 上にあることを示せ．
\end{enumerate}

放物線 $y^2=4px$（$p>0$）上に4点があり，それらを $y$ 座標の大きい順に A，B，C，D とする．線分 AC と BD は放物線の焦点 F で垂直に交わっている．ベクトル $\overrightarrow{\mathrm{FA}}$ が $x$ 軸の正の方向となす角を $\theta$ とする．
\begin{enumerate}
  \item 線分 AF の長さを $p$ と $\theta$ で表せ．
  \item $\dfrac1{\mathrm{AF}}+\dfrac1{\mathrm{CF}}$ は $\theta$ によらず一定であることを示せ．
  \item $\dfrac1{\mathrm{AC}}+\dfrac1{\mathrm{BD}}$ は $\theta$ によらず一定であることを示し，その値を $p$ で求めよ．
\end{enumerate}

極方程式 $r=\dfrac3{2-\cos\theta}$ について，次の問いに答えよ．
\begin{enumerate}
  \item この極方程式を直交座標に関する方程式で表せ．
  \item O を原点とする．曲線上の点 P$(x,y)$ から直線 $x=a$ に下ろした垂線を PH とし，$k=\dfrac{\mathrm{OP}}{\mathrm{PH}}$ とおく．P が曲線上を動くとき $k$ が一定であるとすると，$a$ と $k$ はいくらか．
  \item O を通る直線と曲線の2つの交点を P，P$'$ とするとき，$\dfrac1{\mathrm{OP}}+\dfrac1{\mathrm{OP'}}$ は一定であることを示し，その値を求めよ．
\end{enumerate}

$xy$ 平面上の領域 $x\geqq0,\ y\geqq0$ で，方程式 $x^3+y^3=3xy$ が表す曲線を $C$ とする．正の数 $t$ に対して，直線 $x+y=2t$ が $C$ と異なる2点 Q，R で交わるとき，
\begin{enumerate}
  \item $C$ を極座標 $(r,\theta)$ に関する方程式で表し，$r$ のとりうる値の最大値を求めよ．
  \item $t$ の範囲を求め，Q，R の座標を $t$ を用いて表せ．
  \item 線分 QR の長さが最大となる $t$ の値と，そのときの QR を求めよ．
\end{enumerate}

\begin{enumerate}
  \item 実数を係数とする3次の整式 $P(x)$（3次の係数は1）は2次式 $x^2+ax+b$（$a^2<4b$）で割り切れ，方程式 $P(x)=0$ の3つの解は複素数平面上で正三角形の頂点をなす．$P(x)$ を $a,b$ を用いて表せ．
  \item 実数を係数とする4次方程式 $Q(x)=0$ は異なる4つの解を持ち，それらは複素数平面において同一円周上にあるとする．解の2つが $-1$，$4+3i$ であるとき，他の2つの解を求めよ．
\end{enumerate}

$z=r(\cos\theta+i\sin\theta)$ を，$r>0$，$0\leqq\theta<\frac\pi2$ を満たす複素数とする．
\begin{enumerate}
  \item $z^3=-4\sqrt2+4\sqrt2i$ が成り立つとき，$r$ と $\theta$ を求めなさい．
  \item $\dfrac z3+\dfrac3z$ が実数となるような $r$ と $\theta$ の条件を求めなさい．
  \item $\dfrac z3+\dfrac3z$ が実数で，その値が0以上4以下であるような点 $z$ はどのような図形を描くか．
\end{enumerate}

$z=\cos\dfrac{2\pi}7+i\sin\dfrac{2\pi}7$ とおく．
\begin{enumerate}
  \item $z+z^2+z^3+z^4+z^5+z^6$ を求めよ．
  \item $\alpha=z+z^2+z^4$ とするとき，$\alpha+\bar\alpha$，$\alpha\bar\alpha$ および $\alpha$ を求めよ．
  \item $(2-z)(2-z^2)(2-z^3)(2-z^4)(2-z^5)(2-z^6)$ を求めよ．
\end{enumerate}

$s>0,\ t>1$ とする．複素数平面上の $\alpha=i$，$\beta=2+i$，$\gamma=s+ti$ を表す点をそれぞれ A，B，C とする．さらに，点 D を直線 AC に関して点 B と反対側にとり，$\triangle$ACD が正三角形になるようにする．点 D を表す複素数を $z$ とするとき，
\begin{enumerate}
  \item $z$ を $s,t$ を用いて表せ．
  \item $\alpha,\beta,\gamma$ が等式 $(\gamma-\alpha)^2-2(\beta-\alpha)(\gamma-\alpha)+2(\beta-\alpha)^2=0$ を満たすとき，$\gamma$ と $z$ をそれぞれ求めよ．
  \item (2) で求めた $\gamma$ と $z$ に対して，直線 AC と直線 BD の交点を F とし，$\angle$DFC$=\theta$ とする．F の位置と $\theta$ を求めよ．
\end{enumerate}

複素数平面上で原点 O と2点 A$(\alpha)$，B$(\beta)$ を頂点とする $\triangle$OAB がある．直線 OB に関して点 A と対称な点を C，直線 OA に関して点 B と対称な点を D とする．
\begin{enumerate}
  \item 点 C$(\gamma)$ とするとき，$\gamma=\overline{\left(\dfrac\alpha\beta\right)}\beta$ であることを示せ．
  \item 直線 AD と直線 BC が平行なとき，$\triangle$OAB はどのような三角形か．
\end{enumerate}

複素数平面の点 A$(1)$ を中心とし，原点を通る円を $C$ とする．また，P$(z)$，Q$(w)$ を円 $C$ 上を動く点とし，$0<\arg z<\arg w<\frac\pi2$ とする．さらに $R=\dfrac{z(w-2)}{w(z-2)}$ とおく．
\begin{enumerate}
  \item $R$ は $R>1$ を満たす実数であることを示せ．
  \item $\angle$PAQ$=\dfrac\pi2$ のときの $R$ の最小値を求めよ．
\end{enumerate}

$\alpha=-4+2i$，$\beta=1+2i$ とする．複素数平面において $|z-\alpha|=2|z-\beta|$ をみたす点 $z$ の集合を $C$ とする．
\begin{enumerate}
  \item $C$ は円になることを示し，その円の中心と半径を求めなさい．
  \item 点 $z$ が $z=0$ を除いて $C$ 上を動くとき，$w=\dfrac1z$ で定まる点 $w$ は直線を描くことを示しなさい．
  \item 2点 A$(\alpha)$ と B$(\beta)$ を通る直線を $l$，(2) の直線を $m$ とする．$l$ と $m$ のなす角 $\theta$（$0<\theta\leqq\frac\pi2$）について $\cos\theta$ の値を求めなさい．
\end{enumerate}

2つの複素数 $w,z$ が $w=\dfrac{z+i}{z-1}$ を満たしているとする（$z\neq1$）．
\begin{enumerate}
  \item 点 $z$ が原点を中心とする半径1の円周上を動くとき，点 $w$ はどのような図形を描くか．
  \item 点 $z$ が虚軸上を動くとき，点 $w$ はどのような図形を描くか．
  \item 点 $w$ が実軸上を動くとき，点 $z$ はどのような図形を描くか．
\end{enumerate}

0でない複素数 $z$ に対し，$w=z+\dfrac9z$ とする．
\begin{enumerate}
  \item $z$ が複素数平面上で円 $|z|=1$ 上を動くとき，$w$ が描く図形を求めよ．
  \item $w$ が実数となるような $z$ 全体が表す複素数平面上の図形を求めよ．
  \item $z$ が (2) で求めた図形上にあって，かつ $|z-2|\leqq3$ であるとき，$|z-2-5i|$ の最大値と，そのときの $z$ を求めよ．
\end{enumerate}

複素数平面上の4点 A$(\alpha)$，B$(\beta)$，C$(\gamma)$，D$(\delta)$ を頂点とする凸四角形 ABCD を考える．頂点は反時計回りに A，B，C，D の順に並んでいるとする．四角形 ABCD の外側に，4辺 AB，BC，CD，DA をそれぞれ斜辺とする直角二等辺三角形 APB，BQC，CRD，DSA を作る．
\begin{enumerate}
  \item 点 P を表す複素数を求めよ．
  \item 四角形 PQRS が平行四辺形であるための必要十分条件は，四角形 ABCD がどのような四角形であることか答えよ．
  \item 四角形 PQRS が平行四辺形であるならば，PQRS は正方形であり，その面積は $\dfrac{\mathrm{AB}^2+\mathrm{BC}^2}2+(\text{四角形 ABCD の面積})$ であることを示せ．
\end{enumerate}

楕円 $\dfrac{x^2}4+y^2=1$ について以下の設問に答えよ．
\begin{enumerate}
  \item 原点Oを極として，この楕円の極方程式を求めよ．
  \item 楕円上の2点AとBが $\angle\mathrm{AOB}=\frac\pi2$ であるように動くとき，$M=\dfrac1{\mathrm{OA}^2}+\dfrac1{\mathrm{OB}^2}$ の値を求めよ．
  \item 4点P，Q，R，Sがこの順で楕円上に反時計回りに並んでいて，線分PRと線分QSは原点Oを交点として直交する．Pの偏角を $\theta$（$0\leqq\theta\leqq\frac\pi2$）とするとき，四角形PQRSの面積 $T$ を $\theta$ の式で表せ．さらに，$T$ の最大値と最小値およびそれらを与える $\theta$ の値を求めよ．
\end{enumerate}

定数 $a$ を正の実数とする．円 $x^2-2ax+y^2=0$ に外接し，直線 $x=-a$ にも接する円（中心は直線 $x=-a$ の右側）の中心Pの軌跡を $C$ とする．点 $\mathrm T(-2a,b)$ から曲線 $C$ に引いた2つの接線を $l,l'$ とし，$C$ との接点をそれぞれA，Bとする．
\begin{enumerate}
  \item 曲線 $C$ の方程式を求めよ．
  \item 2つの直線 $l,l'$ は互いに直交することを示せ．
  \item 直線ABは定点を通ることを示し，線分ABの長さを $a,b$ を用いて表せ．
\end{enumerate}

実数 $a,b$ は $a>0$，$b>2$ を満たすとする．2曲線 $C_1:\dfrac{x^2}4-\dfrac{y^2}{a^2}=1$，$C_2:\dfrac{x^2}{b^2}+\dfrac{y^2}4=1$ の第1象限における交点を $\mathrm P(s,t)$ とし，Pにおける2曲線 $C_1,C_2$ の接線をそれぞれ $L_1,L_2$ とする．
\begin{enumerate}
  \item $s$ および $t$ を $a,b$ を用いて表せ．
  \item 2直線 $L_1,L_2$ が直交するとき，$b$ を $a$ で表せ．またこのとき $C_1$ と $C_2$ の焦点が一致することを示せ．
  \item 実数 $a,b$ が (2) の条件を満たしながら変化するとき，Pの軌跡を求めよ．
\end{enumerate}

楕円 $C_1:\dfrac{x^2}{a^2}+\dfrac{y^2}{b^2}=1$ および双曲線 $C_2:\dfrac{x^2}{a^2}-\dfrac{y^2}{b^2}=1$ について，次の問に答えよ．ただし，$a>0$，$b>0$ とする．
\begin{enumerate}
  \item 双曲線 $C_2$ 上の点 $(x_1,y_1)$ における接線の方程式は $\dfrac{x_1x}{a^2}-\dfrac{y_1y}{b^2}=1$ であることを示せ．
  \item 点 $(p,q)$ を通る $C_2$ の2本の接線があり，その接点をそれぞれ $\mathrm A_1,\mathrm A_2$ とする．直線 $\mathrm A_1\mathrm A_2$ の方程式は $\dfrac{px}{a^2}-\dfrac{qy}{b^2}=1$ であることを示せ．
  \item $(p,q)$ が楕円 $C_1$ 上の点であるとき，直線 $\dfrac{px}{a^2}-\dfrac{qy}{b^2}=1$ は $C_1$ に接することを示せ．
\end{enumerate}

双曲線 $\dfrac{x^2}9-\dfrac{y^2}{16}=1$ の右と左の焦点をF，F$'$とする．点Fを通り，傾き $k$ が正の直線 $l$ を，双曲線と2点A，Bで交わるように引く．ただし，A，Bの $x$ 座標はいずれも正とする．
\begin{enumerate}
  \item 焦点Fの $x$ 座標を求めよ．
  \item $k$ のとりうる値の範囲を求めよ．
  \item $\mathrm{F'A}+\mathrm{F'B}=28$ のとき，ABの長さと $k$ の値を求めよ．
\end{enumerate}

整式 $f(x)$ は実数を係数にもつ3次式で，3次の係数は1，定数項は3とする．方程式 $f(x)=0$ は，$-1$ と虚数 $\alpha,\beta$ を解にもつ．$\alpha$ の虚部は正とする．複素数平面上で $\alpha,\beta,-1$ が表す点を順にA，B，Cとする．
\begin{enumerate}
  \item $\alpha$ の絶対値を求めよ．
  \item $\theta$ を $\alpha$ の偏角とする（$0<\theta<\pi$）．$\triangle$ABC の面積 $S$ を $\theta$ を用いて表せ．
  \item $S$ を最大にする $\theta$ とそのときの整式 $f(x)$ を求めよ．
\end{enumerate}

座標平面上の3点 O$(0,0)$，A$(x_1,y_1)$，B$(x_2,y_2)$ を頂点とする$\triangle$OABを考える．$\alpha=x_1+y_1i$，$\beta=x_2+y_2i$ とする．
\begin{enumerate}
  \item $\triangle$OAB の面積 $S$ は $S=\dfrac14|\alpha\bar\beta-\bar\alpha\beta|$ で表されることを示しなさい．
  \item $k$ を4より大きい定数とする．$\alpha,\beta$ が $\alpha^2+\beta^2=4$ かつ $|\alpha-2|+|\alpha+2|=k$ を満たすとき，$u=\alpha+i\beta$，$r=|u|$ とおく．$r+\dfrac4r=k$ を示しなさい．
  \item (2) のとき，$|\alpha|^2+|\beta|^2$ と $\triangle$OAB の面積 $S$ はそれぞれ $\alpha,\beta$ によらず一定であることを示し，$k$ で表しなさい．
\end{enumerate}

複素数 $z$ が $z^4+z^3+z^2+z+1=0$ を満たすとする．このとき，
\begin{enumerate}
  \item $z^5$ の値を求めよ．
  \item $(1+z)(2+2z^2)(3+3z^3)(4+4z^4)$ の値を求めよ．
  \item $-\dfrac\pi2\leqq\arg z\leqq\pi$ であるとき，$|3-z-\bar z|$ を最大とする $z$ の偏角 $\arg z$ を求めよ．
\end{enumerate}

以下の問いに答えよ．
\begin{enumerate}
  \item ド・モアブルの定理を用いて $\sin5\theta$ を $\sin\theta$，$\cos\theta$ およびそれらの累乗で表せ．
  \item 2次方程式 $5x^2-10x+1=0$ を解け．また，その2解が $\dfrac1{\tan^2\frac\pi5}$，$\dfrac1{\tan^2\frac{2\pi}5}$ であることを示せ．
  \item 和 $\dfrac1{\tan^2\frac\pi5}+\dfrac1{\tan^2\frac{2\pi}5}$ と積 $\dfrac1{\tan^2\frac\pi5\tan^2\frac{2\pi}5}$ を求めよ．
\end{enumerate}

複素数 $z=\cos\dfrac{2\pi}7+i\sin\dfrac{2\pi}7$ に対し，$\alpha=z+z^6$ とおく．$f(x)$ は整数係数の3次多項式で，3次の係数が1であり，かつ $f(\alpha)=0$ となるものとする．
\begin{enumerate}
  \item $f(x)$ を求めよ．ただし，$f(x)$ がただ1つに決まることは証明しなくてよい．
  \item 3次方程式 $f(x)=0$ の $\alpha$ 以外の2つの解を，$\alpha$ の2次以下の，整数係数の多項式の形で表せ．
\end{enumerate}

$\alpha$ を実数でない複素数とし，$\beta$ を正の実数とする．以下の問いに答えよ．ただし，複素数 $w$ に対してその共役複素数を $\bar w$ で表す．
\begin{enumerate}
  \item 複素数平面上で，関係式 $\alpha\bar z+\bar\alpha z=|z|^2$ を満たす複素数 $z$ の描く図形を $C$ とする．このとき，$C$ は原点を通る円であることを示せ．
  \item 複素数平面上で，$(z-\alpha)(\beta-\bar\alpha)$ が純虚数となる複素数 $z$ の描く図形を $L$ とする．$L$ は (1) で定めた $C$ と2つの共有点をもつことを示せ．また，その2点をP，Qとするとき，線分PQの長さを $\alpha$ と $\bar\alpha$ を用いて表せ．
  \item $\beta$ の表す複素数平面上の点をRとする．(2) で定めた点P，Qと点Rを頂点とする三角形が $\angle\mathrm R=90^\circ$ の直角二等辺三角形であるとき，$\beta$ を $\alpha$ と $\bar\alpha$ を用いて表せ．また，そのための $\alpha$ の条件を求めよ．
\end{enumerate}

$z$ を複素数とする．複素数平面上の3点 O$(0)$，P$(z)$，Q$(z^2)$ について，
\begin{enumerate}
  \item O，P，Q が鋭角三角形をなすような $z$ の範囲を求め，図示せよ．
  \item O，P，Q が正三角形をなすような $z$ をすべて求めよ．
\end{enumerate}

異なる複素数 $a,b,c$ について，複素数平面上の3点 A$(a)$，B$(b)$，C$(c)$ がこの順に反時計回りの位置にある．三角形ABCの外側に各辺を1辺とする正方形をつくり，辺BC，CA，ABを1辺とする正方形の中心をそれぞれ X，Y，Z とする．
\begin{enumerate}
  \item 点Xを表す複素数 $x$ を $b,c$ で表せ．
  \item $x-a=i(z-y)$ を示し，$\mathrm{AX}=\mathrm{YZ}$ かつ $\mathrm{AX}\perp\mathrm{YZ}$ であることを示せ．ただし $z,y$ は Z，Y を表す複素数とする．
  \item 3直線AX，BY，CZは1点で交わることを示せ．
\end{enumerate}

複素数平面上の原点以外の点 $z$ に対して，$w=\dfrac1z$ とする．
\begin{enumerate}
  \item 点 $z$ が円 $|z-1|=1$ 上（原点を除く）を動くとき，点 $w$ の軌跡を求めよ．
  \item 点 $z$ が1と $i$ を結ぶ線分上を動くときの点 $w$ の軌跡を求め，複素数平面上に図示せよ．
\end{enumerate}

$n$ を3以上の整数とする．半径 $r$（$>0$）の円 $C$ に内接する正 $n$ 角形の $n$ 個の頂点を反時計回りの順に $\mathrm P_0,\mathrm P_1,\dots,\mathrm P_{n-1}$ とおく．点Qが円 $C$ の周上を動くとき，$n$ 個の線分 $\mathrm{QP_0},\mathrm{QP_1},\dots,\mathrm{QP_{n-1}}$ の長さの積 $L(\mathrm Q)$ が最大となるような点Qの位置，及び $L(\mathrm Q)$ の最大値を求めよ．さらに，$r=1$ のとき，
\begin{enumerate}
  \item $n-1$ 本の線分の長さの積 $\mathrm{P_0P_1}\cdot\mathrm{P_0P_2}\cdots\mathrm{P_0P_{n-1}}$ を求めよ．
  \item $\displaystyle\prod_{k=1}^{n-1}\sin\frac{k\pi}n$ を求めよ．
\end{enumerate}

$M$ は有限個の複素数からなる集合で，(a) $1\in M$，$0\notin M$ \quad (b) $z,w\in M$ ならば $zw\in M$ を満たすとする．$\alpha\in M$ とするとき，次の問いに答えよ．
\begin{enumerate}
  \item $\alpha^n=1$ となる自然数 $n$ が存在することを示せ．
  \item $\alpha^{-1}\in M$ であることを示せ．
  \item $\cos\dfrac{2\pi}6+i\sin\dfrac{2\pi}6\in M$ かつ $i\in M$ ならば，$\cos\dfrac{2\pi}{12}+i\sin\dfrac{2\pi}{12}\in M$ であることを示せ．また，このとき $M$ は少なくとも12個の元をもつことを示せ．
\end{enumerate}

円 $O_1:x^2+y^2=4$ 上を点 $(2,0)$ から正の向きに速さ2で，円 $O_2:(x-6)^2+y^2=1$ 上を点 $(6,1)$ から負の向きに速さ1で，2点P，Qが同時に出発して運動する．線分PQの中点をMとする．
\begin{enumerate}
  \item Mの描く軌跡の方程式を求めよ．
  \item 点 $(3,0)$ とMの距離の最大値と最小値を求めよ．
\end{enumerate}

$a$ は実数で，$z=\dfrac{(1-i)^5(a+i)^2}{(a+3i)^2}$ が $|z|=\dfrac{4\sqrt2}3$ をみたすとする．
\begin{enumerate}
  \item $a$ の値を求め，それぞれの場合の $z$ の偏角 $\theta$（$0\leqq\theta<2\pi$）を求めよ．
  \item $z^n$ が実数となる最小の自然数 $n$ と，そのときの $z^n$ を求めよ．
\end{enumerate}

$\alpha=\cos\dfrac{2\pi}7+i\sin\dfrac{2\pi}7$ とする．
\begin{enumerate}
  \item $\alpha,\alpha^2,\dots,\alpha^6$ は $z^7=1$ の相異なる虚数解であることを示せ．
  \item $\displaystyle\prod_{k=1}^6(1-\alpha^k)$，$\displaystyle\prod_{k=1}^6(1+\alpha^k)$，$\displaystyle\prod_{k=1}^6(2-\alpha^k)$ の値を求めよ．
\end{enumerate}

複素数平面上に相異なる3点 P$_1(z_1)$，P$_2(z_2)$，P$_3(z_3)$ がある．
\begin{enumerate}
  \item 三角形P$_1$P$_2$P$_3$ が $\angle\mathrm P_1=90^\circ$ の直角二等辺三角形であるための必要十分条件は，$2z_1^2+z_2^2+z_3^2-2z_1z_2-2z_1z_3=0$ であることを示せ．
  \item 三角形P$_1$P$_2$P$_3$ が正三角形であるための必要十分条件は $z_1^2+z_2^2+z_3^2=z_1z_2+z_2z_3+z_3z_1$ であることを示せ．
  \item $z_1=0$，$z_2=2$ のとき，(1)，(2) のそれぞれをみたす $z_3$ を求めよ．
\end{enumerate}

複素数 $\alpha,\beta$ は $|\alpha|=|\beta|=1$，$\arg\dfrac\beta\alpha=\dfrac\pi2$ をみたす定数とする．
\begin{enumerate}
  \item 複素数 $\gamma$ が $\dfrac{\gamma-\alpha}{\beta-\alpha}$ は実数で $0\leqq\dfrac{\gamma-\alpha}{\beta-\alpha}\leqq1$ をみたすとき，点 $\gamma$ の描く図形を求めよ．
  \item 点 $\gamma$ が (1) の図形上を動くとき，$|z-\gamma|=|\gamma|$ をみたす点 $z$ の存在領域の面積を求めよ．
\end{enumerate}

$n$ を自然数とする．次の等式を証明せよ．
\begin{enumerate}
  \item $\displaystyle\sum_{k=0}^n{}_n\mathrm C_k\cos k\theta=2^n\cos^n\frac\theta2\cos\frac{n\theta}2$
  \item $\displaystyle\sum_{k=0}^n{}_n\mathrm C_k\sin k\theta=2^n\cos^n\frac\theta2\sin\frac{n\theta}2$
  \item $\displaystyle\sum_{k=0}^n{}_n\mathrm C_k\cos\frac{k\pi}3$ を求めよ．
\end{enumerate}

$\alpha=\cos\dfrac{2\pi}7+i\sin\dfrac{2\pi}7$ とし，複素数平面上で $\alpha^k$ を表す点を A$_k$（$k=0,1,\dots,6$）とする．
\begin{enumerate}
  \item A$_0$A$_1$ の長さを求めよ．
  \item A$_0$A$_1\cdot$A$_0$A$_2\cdots$A$_0$A$_6$ と A$_0$A$_1^2+$A$_0$A$_2^2+\dots+$A$_0$A$_6^2$ の値を求めよ．
  \item A$_0$A$_1\cdot$A$_0$A$_2\cdot$A$_0$A$_3$ の値を求めよ．
\end{enumerate}

\begin{enumerate}
  \item $(1+\sqrt3i)^m=(1-i)^n$ をみたす正の整数 $m,n$ のうち，$m$ が最小となるものを求めよ．
  \item $\alpha\neq0$，$\beta,z,z'$ を複素数とする．$z$ と $z'$ が，$\beta$ を通り $\alpha$ の向きの直線に関して対称であるための必要十分条件は $\bar\alpha(z'-\beta)=\alpha\overline{(z-\beta)}$ であることを示せ．
  \item 点 $3$ の，直線 $\{\,i+t(1+i)\mid t\text{ は実数}\,\}$ に関する対称点を求めよ．
\end{enumerate}

$\alpha$ は0でない複素数の定数とし，$w=\dfrac{3z}{z-\alpha}$ とする．
\begin{enumerate}
  \item 点 $z$ が原点を中心とする半径 $|\alpha|$ の円周上（$z\neq\alpha$）を動くとき，点 $w$ の描く図形を求めよ．
  \item 点 $z$ がある円 $C$ 上を動くとき，点 $w$ は原点中心半径1の円を描く．$C$ の中心と半径を $\alpha$ で表し，中心が $i$ となる $\alpha$ を求めよ．
  \item $\alpha$ を (2) の値とし，点 $z$ が実軸上を動くとき，点 $w$ の描く図形を求めよ．
\end{enumerate}

平面上で原点にあった点Pが，$x$ 軸の正の方向に1進む．次に進行方向を左へ $\frac{2\pi}3$ 変えて $\frac12$ 進み，以下同様に左へ $\frac{2\pi}3$ ずつ向きを変え，進む距離を前回の半分にしていく．
\begin{enumerate}
  \item Pの極限の位置を求めよ．
  \item Pが通る点のうち，3回ごとの位置 $\mathrm P_0,\mathrm P_3,\mathrm P_6,\dots$ は一直線上にあることを示せ．
\end{enumerate}

複素数平面上の4点 $0,1,1+i,i$ を頂点とする正方形の周上を点 $z$ が動く．
\begin{enumerate}
  \item 点 $z^2$ はどのような図形を描くか．図示せよ．
  \item (1) の図形で囲まれた領域の面積を求めよ．
\end{enumerate}

三角形OABの外側に2つの正方形 OACD，OBEF を作る（頂点はこの順に回る）．線分DF の中点をR，辺ABの中点をP，正方形OACD，OBEFの中心をM，Nとする．次を証明せよ．
\begin{enumerate}
  \item $2\mathrm{OR}=\mathrm{AB}$，OR$\perp$AB
  \item 三角形MPNは $\angle\mathrm P=90^\circ$ の直角二等辺三角形である．
\end{enumerate}

楕円 $E:\dfrac{x^2}4+y^2=1$ の外部の点 $(p,q)$ から $E$ に2本の接線を引き，その2接点を通る直線を点 $(p,q)$ の極線という．
\begin{enumerate}
  \item 点 $(p,q)$ の極線は $\dfrac{px}4+qy=1$ であることを示せ．
  \item 点 $(4,1)$ の極線と，そのときの2接点を求めよ．
  \item 直線 $x+y=1$ 上にあって $E$ の外部にある任意の点の極線は，ある定点を通ることを示し，その定点を求めよ．
\end{enumerate}

$yz$ 平面上の円 $C:y^2+z^2=1$ と定点 A$(2,0,a)$（$a\neq0$）がある．Aと $C$ 上の点Pを結ぶ直線が $xy$ 平面と交わる点をQとする．
\begin{enumerate}
  \item 点Qが描く曲線の方程式を求めよ．
  \item (1) の曲線が円，楕円（円を除く），放物線，双曲線（の一部）になるための $|a|$ の条件をそれぞれ求めよ．
\end{enumerate}

半径 $r$（$0<r<1$）の円板 $D$ が，原点を中心とする半径1の円に内接しながらすべらずに転がる．$D$ の中心は反時計回りに進み，初めに $D$ の中心と $D$ 上の点Pはそれぞれ $(1-r,0)$，$(1-r+a,0)$（$0<a\leqq r$）にある．
\begin{enumerate}
  \item $D$ の中心が原点のまわりに角 $\theta$ だけ回ったとき，点Pの座標を求めよ．
  \item 点Pがいつか最初の位置に戻るための $r$ の条件を求めよ．
  \item $r=a=\frac13$ のとき，原点とPの距離の最大値と最小値を求め，Pが描く曲線の長さを求めよ．
\end{enumerate}

$\alpha$ は $|\alpha|>1$ をみたす複素数とし，$z\neq-\dfrac1{\bar\alpha}$ とする．
\begin{enumerate}
  \item $\left|\dfrac{\alpha+z}{1+\bar\alpha z}\right|<1$ であることは $|z|>1$ と同値であることを示せ．
  \item $\alpha=2$ とする．$z$ が円 $|z|=\frac13$ 上を動くとき，$\left|\dfrac{2+z}{1+2z}\right|$ の最大値と最小値を求めよ．
\end{enumerate}

複素数 $z=x+yi$（$x,y$ は実数）が $x\geqq-\frac14$ をみたすとする．
\begin{enumerate}
  \item $|1+z|\geqq\dfrac{1+|z|}{\sqrt3}$ が成り立つことを示し，等号が成り立つ $z$ を求めよ．
  \item 定数 $\dfrac1{\sqrt3}$ をこれより大きい数に置き換えると，(1) の不等式は成り立たないことを示せ．
\end{enumerate}

複素数 $z_1,\dots,z_n$，$w_1,\dots,w_n$ について，次を示せ．
\begin{enumerate}
  \item $\displaystyle\left(\sum_{i=1}^n|z_i|^2\right)\left(\sum_{i=1}^n|w_i|^2\right)-\left|\sum_{i=1}^nz_i\bar w_i\right|^2=\sum_{1\leqq i<j\leqq n}|z_iw_j-z_jw_i|^2$
  \item $\left|\sum z_i\bar w_i\right|\leqq\sqrt{\sum|z_i|^2}\sqrt{\sum|w_i|^2}$．また，$w_1,\dots,w_n$ が全部は0でないとき，等号成立は $z_i=kw_i$（$i=1,\dots,n$）となる複素数 $k$ が存在するときに限ることを示せ．
\end{enumerate}

2次方程式 $x^2+ax+b=0$（$a,b$ は実数）が虚数解 $x_1=u+vi$，$x_2=u-vi$（$v>0$）をもち，$u+v=0$ が成り立つ．
\begin{enumerate}
  \item $a>0$，$a^2=2b$ を示せ．
  \item $x_1,x_2$ を原点のまわりに $-\frac\pi4$ 回転した点を $z_1,z_2$ とし，$\alpha=z_1+z_2$，$\beta=z_1z_2$ とする．$\alpha,\beta$ を $a$ で表せ．
  \item $\alpha+\beta$ が実数となるとき，$a,\ z_1,\ z_2,\ \alpha,\ \beta$ を求めよ．
\end{enumerate}

\begin{enumerate}
  \item $|z_1|=|z_2|=|z_3|$，$z_1+z_2+z_3=1$，$z_1z_2z_3=1$ をみたす複素数 $z_1,z_2,z_3$ を求めよ．
  \item $|z_1|=|z_2|=1$，$z_1+z_2=z_1z_2$ をみたす複素数 $z_1,z_2$ を求めよ．
\end{enumerate}

\begin{enumerate}
  \item $\left(\dfrac{\sqrt3+i}{1-i}\right)^n$ が純虚数となる最小の自然数 $n$ と，最大の負の整数 $n$ を求めよ．
  \item 複素数 $z$ が $z+\dfrac1z=\sqrt3$ をみたすとき，$z^{100}+\dfrac1{z^{100}}$ の値を求めよ．
\end{enumerate}

\begin{enumerate}
  \item 方程式 $z^4=-8+8\sqrt3i$ を解き，解を $a+bi$ の形で表せ．また，4つの解を頂点とする四角形の面積を求めよ．
  \item 方程式 $z^3=2\sqrt2i$ を解き，解を $a+bi$ の形で表せ．
\end{enumerate}

正の整数 $m,n$ について $w=\dfrac{(1+\sqrt3i)^m}{(1-i)^n}$ とする．
\begin{enumerate}
  \item $w$ が正の実数となるための $m,n$ の条件を求めよ．
  \item $w$ が正の実数で $m+n$ が最小となる $(m,n)$ と，そのときの $w$ を求めよ．
  \item $w$ が正の実数で $m+n\leqq60$ となる組 $(m,n)$ の個数を求めよ．
\end{enumerate}

点 $z$ が円 $|z-1|=1$ の $\mathrm{Im}\,z\geqq0$ の部分（半円）を動くとき，$w=(\sqrt3+i)z+2i$ で表される点 $w$ を考える．
\begin{enumerate}
  \item 点 $w$ の描く図形を求めよ．
  \item $|w|$ の最大値と最小値を求め，それぞれを与える $z$ を求めよ．
\end{enumerate}

$w=\dfrac1z$ とする．
\begin{enumerate}
  \item 点 $z$ が円 $|z-(1+i)|=\sqrt2$ 上（原点を除く）を動くとき，点 $w$ の描く図形を求めよ．
  \item 点 $z$ が円 $|z-2|=1$ 上を動くとき，点 $w$ の描く図形を求めよ．
\end{enumerate}

$z\neq-i$ に対して $w=\dfrac{z-i}{z+i}$ と定める．
\begin{enumerate}
  \item $z$ が実軸上を動くとき，$w$ の描く図形を求めよ．
  \item $z$ が上半平面 $\mathrm{Im}\,z>0$ を動くとき，$w$ の存在範囲を求めよ．
  \item $z$ が円 $|z-i|=1$ 上（$z\neq-i$ はみたされている）を動くとき，$w$ の描く図形を求めよ．
\end{enumerate}

0でない複素数 $z$ に対して $w=z+\dfrac4z$ とする．
\begin{enumerate}
  \item $z$ が円 $|z|=3$ 上を動くとき，$w=x+yi$ の描く図形の方程式を求めよ．
  \item $w$ が実数となるような $z$ はどのような点か．
  \item $w$ が実数で $0\leqq w\leqq3$ となるような点 $z$ の全体を図示せよ．
\end{enumerate}

複素数 $z$ が $|z|\leqq1$ をみたし，$w=z+1+\sqrt3i$ とする．
\begin{enumerate}
  \item 点 $w$ の存在範囲を図示せよ．
  \item $w^3$ の絶対値を $r$，偏角を $\theta$（$0\leqq\theta<2\pi$）とするとき，$r$ と $\theta$ の値の範囲を求めよ．
\end{enumerate}

原点Oと異なる2点 A$(\alpha)$，B$(\beta)$ について，次の等式が成り立つとき，$\triangle$OAB はどのような三角形か．
\begin{enumerate}
  \item $\alpha^2-\sqrt3\alpha\beta+\beta^2=0$
  \item $\alpha^2-2\alpha\beta+4\beta^2=0$
\end{enumerate}

異なる3点 A$(\alpha)$，B$(\beta)$，C$(\gamma)$ が次の条件をみたすとき，$\triangle$ABC はどのような三角形か．
\begin{enumerate}
  \item $\beta-\alpha=(-1+\sqrt3i)(\gamma-\alpha)$（3辺の比も答えよ）
  \item $\alpha^2+\beta^2+2\gamma^2=2(\alpha+\beta)\gamma$
\end{enumerate}

複素数平面上の三角形OAB（O は原点，A$(\alpha)$，B$(\beta)$）の外心を $z$ とする．
\begin{enumerate}
  \item $z=\dfrac{\alpha\beta(\bar\alpha-\bar\beta)}{\bar\alpha\beta-\alpha\bar\beta}$ を示せ．
  \item $\alpha=1+3i$，$\beta=4$ のとき，外心と外接円の半径を求めよ．
\end{enumerate}

単位円上の異なる3点 A$(\alpha)$，B$(\beta)$，C$(\gamma)$ でできる三角形の垂心を H$(h)$，$h=\alpha+\beta+\gamma$ とする．
\begin{enumerate}
  \item 直線BCに関して点 $z$ と対称な点は $\beta+\gamma-\beta\gamma\bar z$ であることを示せ．
  \item Hの直線BCに関する対称点は $-\dfrac{\beta\gamma}\alpha$ で，単位円上にあることを示せ．
  \item $\alpha=1$，$\beta=i$，$\gamma=-\frac{\sqrt2}2(1+i)$ のとき，H と (2) の点を求めよ．
\end{enumerate}

異なる3点 O$(0)$，A$(\alpha)$，B$(\beta)$ を頂点とする三角形について，次を示し，問いに答えよ．
\begin{enumerate}
  \item $\angle$O 内の傍心（辺ABの外側にある傍接円の中心）を $z$ とすると，$z=\dfrac{|\beta|\alpha+|\alpha|\beta}{|\alpha|+|\beta|-|\beta-\alpha|}$ であることを示せ．
  \item $\alpha=4$，$\beta=3i$ のとき，内心と (1) の傍心を求め，2点間の距離を求めよ．
\end{enumerate}

単位円上の異なる2点 A$(\alpha)$，B$(\beta)$（$\alpha+\beta\neq0$）について答えよ．
\begin{enumerate}
  \item 点Aにおける単位円の接線上の点 $z$ は $z+\alpha^2\bar z=2\alpha$ をみたすことを示せ．
  \item A，Bにおける2本の接線の交点は $\dfrac{2\alpha\beta}{\alpha+\beta}$ であることを示せ．
  \item $\alpha+\beta=0$ のとき (2) の2接線はどうなるか答えよ．また，$\alpha=1$，$\beta=i$ のときの交点を求めよ．
\end{enumerate}

複素数平面上で，点 A$(\alpha)$（$|\alpha|>2$）から原点中心，半径2の円に2本の接線を引き，接点を B$(\beta)$，C$(\gamma)$ とする．
\begin{enumerate}
  \item 直線 BC 上の任意の点 $z$ について $\bar\alpha z+\alpha\bar z=8$ が成り立つことを示せ．
  \item 直線 OA と直線 BC の交点 Q を表す複素数を $\alpha$ で表せ．
  \item $\alpha=3+4i$ のとき，Q を表す複素数と線分 BC の長さを求めよ．
\end{enumerate}

$\beta$ は0でない複素数，$c$ は実数とし，直線 $\ell:\ \bar\beta z+\beta\bar z+c=0$ を考える．
\begin{enumerate}
  \item 点 $z_0$ の $\ell$ に関する対称点を $w$ とするとき，$w=-\dfrac{\beta\bar z_0+c}{\bar\beta}$ を示せ．
  \item 直線 $(1-i)z+(1+i)\bar z=4$ は $xy$ 座標でどのような直線か．この直線に関して点 $3+2i$ と対称な点を求めよ．
\end{enumerate}

\begin{enumerate}
  \item 点 $z$ を，原点と $1+i$ を通る直線に関して対称移動し，さらに原点と $\sqrt3+i$ を通る直線に関して対称移動した点を $w$ とする．$w$ を $z$ で表し，この合成移動が原点を中心とする回転であることを示して回転角を求めよ．
  \item 異なる2点 A$(\alpha)$，B$(\beta)$ を通る直線に関して点 $\gamma$ と対称な点 $\delta$ は $\delta=\dfrac{\alpha-\beta}{\bar\alpha-\bar\beta}(\bar\gamma-\bar\beta)+\beta$ であることを示し，2点 $2$，$2i$ を通る直線に関して原点と対称な点を求めよ．
\end{enumerate}

3点 $1,\ z,\ z^2$ が三角形の頂点となるような複素数 $z$ を考える．
\begin{enumerate}
  \item 3点が三角形をつくる（同一直線上にない）ための $z$ の条件を求めよ．
  \item 頂点 $z$ の角が直角となる $z$，頂点1の角が直角となる $z$，頂点 $z^2$ の角が直角となる $z$ の全体を，それぞれ複素数平面上に図示せよ．
  \item $|z|=1$，$\mathrm{Im}\,z>0$ のとき，三角形の面積の最大値と，そのときの $z$ を求めよ．
\end{enumerate}

実数係数の3次方程式 $x^3+sx^2+tx+u=0$ が異なる虚数解 $\alpha,\beta$ と実数解 $\gamma$ をもつ．3点 $\alpha,\beta,\gamma$ が1辺の長さ2の正三角形をなし，さらに $\alpha\beta+\beta\gamma+\gamma\alpha=0$ が成り立つ．
\begin{enumerate}
  \item $\alpha,\beta$ を $\gamma$ で表せ（2通り）．
  \item 組 $(s,t,u)$ をすべて求めよ．
  \item (2) の結果から，正三角形の重心は原点であることを確かめよ．
\end{enumerate}

$z_0=2(\cos\theta+i\sin\theta)$（$0<\theta<\frac\pi2$），$z_1=\dfrac{1+i}2z_0$，$z_2=-\dfrac2{z_0}$ を表す点をそれぞれ P$_0$，P$_1$，P$_2$ とする．
\begin{enumerate}
  \item $z_1$，$z_2$ を極形式で表せ．
  \item $\angle\mathrm{OP_1P_0}=\frac\pi2$ を示せ．
  \item 4点 O，P$_0$，P$_1$，P$_2$ が同一円周上にあるときの $z_0$ を求めよ．
\end{enumerate}

$z_1=0$，$z_2=2$，$z_3=1+i$ とし，これらと異なる複素数 $z_4$ に対して $w=\dfrac{(z_1-z_3)(z_2-z_4)}{(z_1-z_4)(z_2-z_3)}$ とする．
\begin{enumerate}
  \item $z_4=1-i$ のとき $w$ を求めよ．
  \item $w$ が実数となる $z_4$ の全体を求めよ．
  \item $z_4$ が (2) の図形上を動くとき，$w$ が正となるのは $z_4$ がどの部分にあるときか．
\end{enumerate}

四角形ABCDの頂点を A$(\alpha)$，B$(\beta)$，C$(\gamma)$，D$(\delta)$ とし，対角線 AC，BD の中点を M，N とする．
\begin{enumerate}
  \item $\mathrm{AB}^2+\mathrm{BC}^2+\mathrm{CD}^2+\mathrm{DA}^2=\mathrm{AC}^2+\mathrm{BD}^2+4\mathrm{MN}^2$ を証明せよ．
  \item $\mathrm{AB}^2+\mathrm{BC}^2+\mathrm{CD}^2+\mathrm{DA}^2=\mathrm{AC}^2+\mathrm{BD}^2$ となるのは四角形ABCDが平行四辺形のときに限ることを示せ．
\end{enumerate}

$z_1=0$，$z_{n+1}=(1+\sqrt3i)z_n+2$ で定まる数列 $\{z_n\}$ について，$z_n$ を表す点を P$_n$ とする．
\begin{enumerate}
  \item $z_n$ を求めよ．
  \item $\angle\mathrm P_n\mathrm P_{n+1}\mathrm P_{n+2}$ と三角形 P$_n$P$_{n+1}$P$_{n+2}$ の面積を求めよ．
  \item 点 P$_n$ はすべて，ある点を中心とする「回転しながら半径が2倍ずつになる」渦巻きの上にある．その中心と，中心から P$_n$ までの距離を求めよ．
\end{enumerate}

\begin{enumerate}
  \item 楕円 $\dfrac{x^2}9+\dfrac{y^2}4=1$ に外接する長方形の頂点はすべて定円上にあることを示し，その円を求めよ．また，このような長方形の面積 $S$ のとり得る値の範囲を求めよ．
  \item 楕円の中心Oから互いに垂直な2本の半直線を引き，楕円との交点をP，Qとするとき，$\dfrac1{\mathrm{OP}^2}+\dfrac1{\mathrm{OQ}^2}$ は一定であることを示し，その値を求めよ．
  \item 双曲線 $\dfrac{x^2}9-\dfrac{y^2}4=1$ に，互いに垂直な2本の接線が引ける点の全体を求めよ．
\end{enumerate}

\begin{enumerate}
  \item 中心が点 $\left(2,\dfrac\pi3\right)$ で極Oを通る円 $C$ の極方程式を求めよ．
  \item 直線OCに垂直で，極からの距離が3である直線のうち，$\theta=\frac\pi3$ の向きにあるもの $\ell$ の極方程式を求めよ．
  \item $C$ と $\ell$ の交点の極座標と，$C$ が $\ell$ から切り取る弦の長さを求めよ．
  \item 2点 A$\left(4,\dfrac\pi6\right)$，B$\left(4,\dfrac\pi2\right)$ を通る直線の極方程式を求めよ．
\end{enumerate}

点 $(2,0)$ を中心とする半径1の円 $C$ がある．原点Oから $C$ の各接線に下ろした垂線の足をPとする．
\begin{enumerate}
  \item Oを極，$x$ 軸の正の部分を始線とするとき，Pの軌跡の極方程式は $r=1+2\cos\theta$ であることを示せ．
  \item この曲線のうち $r<0$ となる部分（内側のループ）が囲む部分の面積を求めよ．
  \item 曲線全体の外側の境界で囲まれる部分の面積を求めよ．
\end{enumerate}

点 F$(2,0)$ と直線 $\ell:x=8$ がある．点Pから $\ell$ に下ろした垂線をPHとするとき，PF$:$PH$=1:2$ をみたす点Pの軌跡を $E$ とする．
\begin{enumerate}
  \item $E$ の方程式を求めよ．
  \item Fを極，Fから $x$ 軸の正の向きの半直線を始線として，$E$ の極方程式を求めよ．
  \item 原点を極，$x$ 軸の正の部分を始線とする $E$ の極方程式を求めよ．
\end{enumerate}

楕円 $E:\dfrac{x^2}{16}+\dfrac{y^2}{12}=1$ の焦点 F$(2,0)$ を通る弦を考える．
\begin{enumerate}
  \item Fを通る弦PQについて，$\dfrac1{\mathrm{FP}}+\dfrac1{\mathrm{FQ}}$ は弦の向きによらず一定であることを示し，その値を求めよ．
  \item Fを通る互いに垂直な2つの弦PQ，RSについて，$\dfrac1{\mathrm{PQ}}+\dfrac1{\mathrm{RS}}$ と $\dfrac1{\mathrm{FP}\cdot\mathrm{FQ}}+\dfrac1{\mathrm{FR}\cdot\mathrm{FS}}$ はそれぞれ一定であることを示し，その値を求めよ．
\end{enumerate}

複素数平面上で，点Pは時刻0に原点にあり，時刻1まで実軸の正の方向に速さ1で動く．時刻 $n$（$n=1,2,\dots$）に点 $\mathrm Q_n(z_n)$ で進行方向を $\frac\pi3$ 回転し，時刻 $n+1$ まで速さ $\left(\frac12\right)^n$ で進む．$\alpha=\dfrac{1+\sqrt3i}4$ とする．
\begin{enumerate}
  \item $z_n$ を $\alpha,n$ で表せ．
  \item $z_n$ が近づく点 $w$ を求めよ．
  \item $z_n$ の実部が $w$ の実部より大きくなる $n$ をすべて求めよ．
\end{enumerate}

$z_1,z_2,z_3,z_4$ は絶対値1の互いに異なる複素数とする．
\begin{enumerate}
  \item $z_1+z_2+z_3=1$ ならば，$z_1,z_2,z_3$ のいずれかは1で，残りの2つは原点に関して対称であることを示せ．
  \item $z_1+z_2+z_3+z_4=0$ ならば，4点 $z_1,\dots,z_4$ を適当な順に結ぶと長方形になることを示せ．
\end{enumerate}

原点Oを中心とする半円 $C:x^2+y^2=1$（$y>0$）上の点をPとする．$a>1$ に対し A$(-a,0)$ とし，直線APと $y$ 軸の交点をQ，Qを通り $x$ 軸に平行な直線と直線OPの交点をRとする．
\begin{enumerate}
  \item OP が $x$ 軸の正の方向となす角を $\theta$，OR$=r$ とするとき，$r$ を $a,\theta$ で表せ．
  \item 点Pが $C$ 上を動くとき，点Rの描く曲線の方程式を求め，その離心率を求めよ．
\end{enumerate}

$z$ を虚数とする．
\begin{enumerate}
  \item $z+\dfrac4z$ が実数となるとき，$|z|$ を求めよ．
  \item $z+\dfrac4z$ が整数となる $z$ はいくつあるか．また，そのうち実部が正であるものをすべて求めよ．
\end{enumerate}

$z_1=1$，$z_{n+1}=iz_n+2$（$n=1,2,\dots$）で定まる複素数の数列を考える．
\begin{enumerate}
  \item $z_{n+1}-\alpha=i(z_n-\alpha)$ をみたす $\alpha$ を求め，$z_n$ を求めよ．
  \item $z_n=1+2i$ となる $n$ をすべて求めよ．
  \item $\displaystyle\sum_{k=1}^{100}z_k$ を求めよ．
\end{enumerate}

$0<\theta<\pi$，$\theta\neq\frac\pi2$ とし，$z=1+\cos2\theta+i\sin2\theta$ とする．
\begin{enumerate}
  \item $z$ を極形式で表せ（$\theta<\frac\pi2$，$\theta>\frac\pi2$ で分けよ）．
  \item $z^{2026}$ が正の実数となる $\theta$ の個数を求めよ．
  \item $z^{2027}$ が正の実数となる $\theta$ の個数を求めよ．
\end{enumerate}

$k$ は0でない実数とし，方程式 $x^3-(2k+2)x^2+(2k^2+4k)x-4k^2=0$ の3解を複素数平面上の点 A，B，C とみなす．
\begin{enumerate}
  \item 3解を求めよ．
  \item 三角形ABCが直角三角形となる $k$ と，正三角形となる $k$ を求めよ．
  \item 三角形ABCの外接円が原点を通る $k$ を求め，(2) との関係を説明せよ．
\end{enumerate}

$z=\cos\theta+i\sin\theta$（$0<\theta<\pi$），$\alpha=z+1$，$\beta=z-1$ とする．
\begin{enumerate}
  \item $\alpha,\beta$ を極形式で表せ（$\arg\beta$ は $0$ 以上 $2\pi$ 未満）．
  \item $\theta=\frac{2\pi}3$ のとき，9つの複素数 $\alpha^m\beta^n$（$m,n=1,2,3$）の実部の最大値と最小値，およびそれらを与える $(m,n)$ をすべて求めよ．
\end{enumerate}

$z=\cos\frac{2\pi}{11}+i\sin\frac{2\pi}{11}$ とし，$\alpha=z+z^3+z^4+z^5+z^9$ とする．
\begin{enumerate}
  \item $\bar\alpha=z^2+z^6+z^7+z^8+z^{10}$ を示し，$\alpha+\bar\alpha$ を求めよ．
  \item $\alpha\bar\alpha=3$ を示し，$\alpha$ を求めよ．
  \item $\displaystyle\prod_{k=1}^{10}(1-z^k)$ と $\displaystyle\prod_{k=1}^{10}(1+z^k)$ を求めよ．
\end{enumerate}

$a_1=1$，$a_2=2i$，$a_{n+2}=a_{n+1}+a_n$ で複素数の数列を定め，$b_n=\dfrac{a_{n+1}}{a_n}$ とする．
\begin{enumerate}
  \item $b_1,b_2,b_3,b_4$ を求め，$b_1,b_2,b_3$ を通る円 $C$ の中心と半径を求めよ．
  \item $b_4$ も $C$ 上にあることを確かめ，すべての $b_n$ が $C$ 上にあることを示せ．
\end{enumerate}

$w=\dfrac1{z-\alpha}$（$\alpha$ は複素数の定数）とする．点 $z$ が単位円 $|z|=1$ 上（$z\neq\alpha$）を動く．
\begin{enumerate}
  \item 点 $w$ がある直線上を動くための $\alpha$ の条件を求めよ．
  \item $\alpha=i$ のとき，$w$ の描く図形を求めよ．
  \item $\alpha=2$ のとき，$w$ の描く図形を求めよ．
\end{enumerate}

$\alpha$ を実数でない複素数，$\beta$ を正の実数とする．
\begin{enumerate}
  \item $\alpha\bar z+\bar\alpha z=|z|^2$ をみたす $z$ の描く図形 $C$ は，原点を通る円であることを示せ．
  \item $(z-\alpha)(\beta-\bar\alpha)$ が純虚数または0となる $z$ の描く図形 $L$ は，$C$ の中心を通る直線であることを示し，$L$ と $C$ の2交点 P，Q の距離を求めよ．
  \item 点 R$(\beta)$ について，三角形PQRが $\angle\mathrm R=90^\circ$ の直角二等辺三角形となるとき，$\beta$ を $\alpha,\bar\alpha$ で表せ．また，そのとき R は $C$ 上にあることを示せ．
\end{enumerate}

$z$ を実数でない複素数とする．3点 A$(1)$，B$(z)$，C$(z^2)$ を考える．
\begin{enumerate}
  \item $\dfrac{z^2-z}{1-z}$，$\dfrac{z^2-1}{z-1}$，$\dfrac{1-z^2}{z-z^2}$ を簡単にせよ．
  \item 三角形ABCが直角三角形となる $z$ の描く図形を求めよ．
  \item 三角形ABCが鋭角三角形で，かつ $|z|<1$ となる $z$ の範囲の面積を求めよ．
\end{enumerate}

$r>1$，$w=r\left(\cos\frac\pi{12}+i\sin\frac\pi{12}\right)$ とし，$z_1=w$，$z_{n+1}=z_nw^n$ で数列を定める．原点をO，$z_n$ を表す点を P$_n$ とする．
\begin{enumerate}
  \item $|z_n|$ と $z_n$ の偏角の1つを $n$ で表せ．
  \item $3\leqq n\leqq30$ のとき，三角形P$_n$OP$_{n+1}$ が $\angle\mathrm O=\frac\pi3$ の直角三角形となる $n$ と $r$ をすべて求め，そのときの $z_n$ の偏角 $\theta$（$0\leqq\theta<2\pi$）を求めよ．
\end{enumerate}

$k>0$ とする．放物線 $y^2=4kx$ ……① を考える．
\begin{enumerate}
  \item ①上の点 $(kt^2,2kt)$ における法線と $x$ 軸の交点を求めよ．
  \item 点 $(4k,0)$ を通り，中心が $x$ 軸上にあって，①と2つの共有点をもち，その共有点で共通の接線をもつ円の方程式を求めよ．
  \item (2) の円と①の共通接線の方程式を求めよ．
\end{enumerate}

楕円 $\dfrac{x^2}{a^2}+\dfrac{y^2}{b^2}=1$（$a>b>0$）の第2象限の点Pにおける接線を $l$ とし，原点Oを通り $l$ に平行な直線 $m$ と楕円の第1象限の交点をA，Pから $m$ に下ろした垂線の足をBとする．
\begin{enumerate}
  \item $\mathrm{OA}\cdot\mathrm{PB}=ab$ を示せ．
  \item $\mathrm{OA}^2+\mathrm{OP}^2=a^2+b^2$ を示せ．
  \item $a=2$，$b=1$，$\mathrm{OP}=\sqrt3$ のとき，PB の長さを求めよ．
\end{enumerate}

双曲線 $C:x^2-y^2=2$ と点 F$(2,0)$ がある．F を通り $x$ 軸とのなす角が $\theta$，$\theta+\frac\pi4$ の直線を $l$，$m$ とする（$\theta$ は $\frac\pi4$ の整数倍でない）．
\begin{enumerate}
  \item F は $C$ の焦点であることを確かめ，$l$ と $C$ の交点を P，Q とするとき $\mathrm{PQ}^2$ を $\theta$ で表せ．
  \item $m$ と $C$ の交点を R，S とするとき，$\dfrac1{\mathrm{PQ}^2}+\dfrac1{\mathrm{RS}^2}$ の値を求めよ．
\end{enumerate}

楕円 $\dfrac{x^2}{16}+\dfrac{y^2}9=1$ と直線 $l:y=x+k$ がある．
\begin{enumerate}
  \item $l$ が楕円と2つの共有点をもつための $k$ の条件を求めよ．
  \item 2共有点を P，Q とする（$k\neq0$）．三角形OPQの面積を最大にする $k$ と，最大値を求めよ．
\end{enumerate}

楕円 $\dfrac{x^2}{a^2}+\dfrac{y^2}{b^2}=1$（$a>b>0$）と双曲線 $\dfrac{x^2}{a^2}-\dfrac{y^2}{c^2}=1$（$c>0$）を考える．双曲線上の点 P$(s,t)$（$s,t>0$）と原点を結ぶ線分が楕円と交わる点を Q，P における双曲線の接線が $x$ 軸と交わる点を A，Q における楕円の接線が $x$ 軸と交わる点を B とする．PA$\perp$QB となるように P をとる．
\begin{enumerate}
  \item P の座標を $a,b,c$ で表せ．
  \item A，B はそれぞれ楕円，双曲線の焦点であることを示せ．
  \item $a^2-b^2=\frac14$，$a^2+c^2=1$ をみたしながら $a,b,c$ が変わるとき，直線PAとQBの交点Rの $y$ 座標が最大となる $a,b,c$ を求めよ．
\end{enumerate}

円 $C_0:x^2+y^2=1$，楕円 $C_1:\dfrac{x^2}{a^2}+\dfrac{y^2}{b^2}=1$（$a,b>1$）がある．
\begin{enumerate}
  \item $C_1$ 上の点 P，Q が $\mathrm{OP}\perp\mathrm{OQ}$ をみたすとき，$\dfrac1{\mathrm{OP}^2}+\dfrac1{\mathrm{OQ}^2}=\dfrac1{a^2}+\dfrac1{b^2}$ を示せ．
  \item $C_1$ 上のどの点 P に対しても，P を頂点にもち $C_0$ に外接し $C_1$ に内接する平行四辺形が存在するための条件は $\dfrac1{a^2}+\dfrac1{b^2}=1$ であることを示せ．
  \item $a=2$ として (2) の条件をみたすとき，そのような平行四辺形の面積のとり得る値の範囲を求めよ．
\end{enumerate}

定数 $k$ に対して $f(t)=2^{k+t}+2^{k-t}$，$g(t)=2^{k+t}-2^{k-t}$ とする．すべての実数 $t$ で $f(2t)=\{f(t)\}^2+\{g(t)\}^2$ が成り立つ．
\begin{enumerate}
  \item $k$ と $\{f(t)\}^2-\{g(t)\}^2$ の値を求めよ．
  \item 曲線 $x=f(t)+2g(t)$，$y=g(t)$ の方程式を求め，どのような図形か答えよ．
\end{enumerate}

媒介変数 $t$（$t\neq0$）で $x=t+\dfrac1t$，$y=3t-\dfrac3t+2$ と表される曲線 $H$ を考える．
\begin{enumerate}
  \item $t$ を消去して $H$ の方程式を求め，$H$ は双曲線全体であることを示せ．
  \item 直線 $y=ax+5$ と $H$ の共有点の個数を，$a$ の値で分類せよ．
\end{enumerate}

楕円 $\dfrac{x^2}4+y^2=1$ の第1象限の点 P における法線と $x$ 軸，$y$ 軸で囲まれる三角形の面積を $S$ とする．
\begin{enumerate}
  \item P$(2\cos\theta,\sin\theta)$ として，法線の $x$ 切片，$y$ 切片を求めよ．
  \item $S$ の最大値と，そのときの P を求めよ．
  \item 三角形が直角二等辺三角形となる P を求めよ．
\end{enumerate}

半径 $\frac a2$ の円板 $C$ が，原点中心半径 $a$ の定円に内接しながらすべらずに回転する．$C$ の中心と原点を結ぶ線分が $x$ 軸の正の向きとなす角を $\theta$ とし，最初 $\theta=0$ とする．
\begin{enumerate}
  \item $C$ の周上の点 P が最初 $(a,0)$ にあるとき，P の座標を $\theta$ で表し，P は $x$ 軸上の線分を往復することを示せ．
  \item $C$ 上で中心から距離 $d$（$0<d<\frac a2$）の点 Q が最初 $\left(\frac a2+d,0\right)$ にあるとき，Q の描く曲線の方程式を求めよ．
\end{enumerate}

$0<t<2$ とする．円 $A:x^2+y^2=4$ と点 F$(t,0)$ がある．$A$ 上の点 P で $A$ に内接し F を通る円を $B$ とし，$B$ の中心の軌跡を $C$ とする．
\begin{enumerate}
  \item $C$ の方程式を求めよ．
  \item 原点を極とする $C$ の極方程式を求めよ．
  \item P が $A$ 上を，Q が $C$ 上を動くときの PQ の最大値を $f(t)$ とする．$f(t)$ と，そのとり得る値の範囲を求めよ．
\end{enumerate}

半直線 OA，OB は $x$ 軸の正の向きとそれぞれ $\frac\pi3$，$-\frac\pi3$ の角をなす．長さ1の線分PQの両端が OA，OB 上（O を除く）を動く．
\begin{enumerate}
  \item $\alpha=\angle\mathrm{OPQ}$ として OP，OQ を $\alpha$ で表せ．
  \item PQ の中点 M の軌跡の方程式を求めよ．
  \item O から直線PQに下ろした垂線の足 H の軌跡を，原点を極とする極方程式で表せ．
\end{enumerate}

双曲線 $\dfrac{x^2}4-y^2=1$ の第4象限の部分を $C$ とし，A$(2,0)$ とする．$C$ 上の点 Q における接線 $l$ に原点 O から下ろした垂線の足を P とする．
\begin{enumerate}
  \item P の軌跡は，O を極とする極方程式 $r^2=4\cos^2\theta-\sin^2\theta$（$r>0$，$0<\theta<\alpha$）で表されることを示せ．ここで $\alpha$ は $\tan\alpha=2$ をみたす鋭角とする．
  \item 三角形OAPの面積を最大にする P の直交座標と，最大値を求めよ．
\end{enumerate}

楕円 $E:\dfrac{x^2}{25}+\dfrac{y^2}9=1$ の内部に定点 C$(3,1)$ がある．$E$ の外部の点Pから $E$ に引いた2本の接線の接点をA，Bとすると，弦ABはつねにCを通るという．
\begin{enumerate}
  \item 点Pはある直線 $l$ 上にあることを示し，$l$ の方程式を求めよ．
  \item 原点OとPの距離の最小値を求めよ．
  \item 弦ABの中点の軌跡を求めよ．
\end{enumerate}

$n$ を2以上の自然数とし，$f_k(x)=(1+x+x^2+\dots+x^k)^{k+1}$（$k=1,2,\dots,n$），$g(x)=f_1(x)f_2(x)\cdots f_n(x)$ とする．$g(x)$ の次数を $l$ とし，$g(x)=a_0+a_1x+\dots+a_lx^l$ と表す．
\begin{enumerate}
  \item $l$ と $a_1$ を求めよ．
  \item 方程式 $g(x)=0$ の $l$ 個の解（重解は重複度だけ数える）の総和を求めよ．
  \item $l$ 個の解の2乗の総和を求めよ．
\end{enumerate}

\begin{enumerate}
  \item 複素数平面上の相異なる3点 A$(\alpha)$，B$(\beta)$，C$(\gamma)$ について，$\triangle$ABC が正三角形であるための必要十分条件は $\alpha^2+\beta^2+\gamma^2=\alpha\beta+\beta\gamma+\gamma\alpha$ であることを示せ．
  \item 実数 $p,q$ について，3次方程式 $z^3-3z^2+pz+q=0$ の3つの解が複素数平面上で正三角形の頂点となり，その外接円の半径が2であるとき，$p,q$ の値と3つの解を求めよ．
\end{enumerate}

$|\lambda|=1$，$|\alpha|\neq1$ である複素数 $\lambda,\alpha$ に対して $f(z)=\lambda\dfrac{z-\alpha}{1-\bar\alpha z}$ とし，$C$ を単位円 $|z|=1$ とする．
\begin{enumerate}
  \item $|f(z)|^2-1=\dfrac{(|z|^2-1)(1-|\alpha|^2)}{|1-\bar\alpha z|^2}$ を示し，$f$ は $C$ を $C$ に移すことを示せ．
  \item $z\neq0,\ \frac1{\bar\alpha}$ のとき $f\!\left(\dfrac1{\bar z}\right)=\dfrac1{\overline{f(z)}}$ を示せ．
  \item $f(2)=2$，$f(i)=-i$ をみたす $f$（すなわち $\lambda,\alpha$）を求めよ．また，この $f$ は $C$ の内部をどこへ移すか答えよ．
\end{enumerate}

$\alpha=\cos\dfrac{2\pi}7+i\sin\dfrac{2\pi}7$ とする．
\begin{enumerate}
  \item $\displaystyle S_1=\sum_{k=1}^6\frac1{2-\alpha^k}$ の値を求めよ．
  \item $\displaystyle S_2=\sum_{k=1}^6\frac1{(2-\alpha^k)^2}$ の値を求めよ．
\end{enumerate}

\begin{enumerate}
  \item 実数 $a$ がすべての実数値をとって変わるとき，$z^2-az+2a=0$ をみたす複素数 $z$ が描く図形を求めよ．
  \item $z$ が (1) の図形上にあって $|z|\leqq3$ をみたすとき，$|z-1-i|$ の最大値と最小値を求めよ．
\end{enumerate}

複素数 $\alpha$ は2点 $i$ と $1+i$ を結ぶ線分上を動き，複素数 $\beta$ は原点を中心とする半径1の円周上を動く．
\begin{enumerate}
  \item $\alpha+\beta$ が動く範囲の面積を求めよ．
  \item $\alpha\beta$ が動く範囲の面積を求めよ．
  \item $\alpha^2$ が描く曲線と実軸・虚軸で囲まれた部分の面積を求めよ．
\end{enumerate}

複素数平面上に3点 A$(\alpha)$，B$(\alpha^3)$，C$(\alpha^5)$ がある．
\begin{enumerate}
  \item この3点を頂点とする正三角形ができるような複素数 $\alpha$ をすべて求めよ．
  \item (1) の正三角形の面積を求めよ．また，その外心はどこか．
\end{enumerate}

$\alpha=2+i$，$\beta=1+3i$ とし，点 P$(z)$ が $z\bar\beta-\bar z\beta=\alpha\bar\beta-\bar\alpha\beta$ をみたすとする．
\begin{enumerate}
  \item 点 P の描く図形を求め，$z=x+yi$ として $x,y$ の方程式で表せ．
  \item $|z|$ の最小値と，そのときの $z$ を求めよ．
  \item 原点の，(1) の図形に関する対称点を求めよ．
\end{enumerate}

3次方程式 $z^3+z^2+2z+3=0$ の解を $z=x+yi$ として点 $(x,y)$ を考える．
\begin{enumerate}
  \item このような点のうち円 $x^2+y^2=1$ の外側にあるものは何個か．
  \item このような点のうち円 $x^2+y^2=2$ の外側にあるものは何個か．
\end{enumerate}

$n$ を自然数とし，$z^{2n+1}=1$ の相異なる解を $1,\alpha_1,\dots,\alpha_{2n}$，それらを表す点を $\mathrm A_0(1)$，$\mathrm A_k(\alpha_k)$ とする．
\begin{enumerate}
  \item $\displaystyle\prod_{k=1}^{2n}(1+\alpha_k+\alpha_k^2)$ の値を求めよ．
  \item $\alpha_1^3,\alpha_2^3,\dots,\alpha_{2n}^3$ が $\alpha_1,\dots,\alpha_{2n}$ の並べ替えになるための $n$ の条件を求めよ．
  \item $\displaystyle\sum_{k=1}^{2n}\mathrm A_0\mathrm A_k^2$ と $\displaystyle\prod_{k=1}^{2n}\mathrm A_0\mathrm A_k$ の値を求めよ．
\end{enumerate}

$x^4$ の係数が1である実数係数の4次式 $f(x)$ について，$\alpha$ が方程式 $f(x)=0$ の解ならば $\alpha^2$ も解であるという．
\begin{enumerate}
  \item 方程式 $f(x)=0$ の解の絶対値は0または1であることを示せ．
  \item 方程式 $f(x)=0$ が相異なる4つの解をもつとき，$f(x)$ をすべて求めよ．
\end{enumerate}

三角形 ABC の外接円を単位円とし，A，B，C を表す複素数を $a,b,c$ とする．単位円上の点 D$(d)$ から直線 BC，CA，AB に下ろした垂線の足を P，Q，R とする．
\begin{enumerate}
  \item 単位円上の2点 $u,v$ を通る直線に D から下ろした垂線の足は $\dfrac12\left(u+v+d-\dfrac{uv}d\right)$ であることを示せ．
  \item P，Q，R は一直線上にあることを示せ（シムソンの定理）．
  \item 点 D と，D の外接円の中心に関する対称点 D$'$ について，それぞれのシムソン線は直交することを示せ．
\end{enumerate}

$x,y$ は同時に0にならない実数とする．
\begin{enumerate}
  \item $z=\dfrac{x^2+2y^2}{x^2-xy+y^2}$ の最大値と最小値を求めよ．
  \item 定数 $k$ に対して $z=\dfrac{x^2+kxy+2y^2}{x^2-xy+y^2}$ の最大値が3となるような $k$ をすべて求め，それぞれの場合の最小値を求めよ．
\end{enumerate}

$\alpha>\beta$ とし，座標軸上にない点 P$(p,q)$ を考える．
\begin{enumerate}
  \item $\dfrac{p^2}{\alpha-t}+\dfrac{q^2}{\beta-t}=1$ をみたす $t$ は，$t_1<\beta<t_2<\alpha$ の2つであることを示せ．$t=t_1$ では楕円，$t=t_2$ では双曲線となり，どちらも焦点は $(\pm\sqrt{\alpha-\beta},0)$ であることを確かめよ．
  \item 2曲線は P において直交することを示せ．
  \item $\alpha=5$，$\beta=1$，P$(2,3)$ のとき，2曲線の方程式と，P における2本の接線の傾きを求めよ．
\end{enumerate}

双曲線 $H:\dfrac{x^2}4-\dfrac{y^2}2=1$ の焦点を F$(\sqrt6,0)$，F$'(-\sqrt6,0)$ とする．
\begin{enumerate}
  \item $H$ 上の点 P における接線と2本の漸近線の交点を Q，R とする．P は線分 QR の中点であることを示し，OQ$\cdot$OR と $\triangle$OQR の面積を求めよ．
  \item F，F$'$ から P における接線に下ろした垂線の足は，原点を中心とする定円上にあることを示し，その半径を求めよ．
  \item F を通り互いに直交する2本の直線が $H$ と交わってできる弦を AB，CD とする．AB，CD がともに $H$ の右側の枝の2点を結ぶとき $\dfrac1{\mathrm{AB}}+\dfrac1{\mathrm{CD}}$ は一定であることを示し，その値を求めよ．また，一方が両方の枝を結ぶときは $\left|\dfrac1{\mathrm{AB}}-\dfrac1{\mathrm{CD}}\right|$ が一定であることを示せ．
\end{enumerate}

$n$ を自然数とする．
\begin{enumerate}
  \item 0 でない複素数 $\alpha_1,\dots,\alpha_{2n+1}$ について，$\alpha_1\alpha_2,\ \alpha_2\alpha_3,\ \dots,\ \alpha_{2n}\alpha_{2n+1},\ \alpha_{2n+1}\alpha_1$ がすべて実数であるとする．このとき，$\alpha_1,\dots,\alpha_{2n+1}$ はすべて実数であるか，すべて純虚数であることを示せ．
  \item (1) で，さらにこれらの積がすべて正であるとき，$\alpha_k$ はすべて同符号の実数であることを示せ．
  \item 項数が偶数の場合，$\alpha_1\alpha_2,\ \alpha_2\alpha_3,\ \alpha_3\alpha_4,\ \alpha_4\alpha_1$ がすべて正の実数であっても，$\alpha_1,\dots,\alpha_4$ が実数でも純虚数でもない例をあげよ．
\end{enumerate}

平面上に3点 $\mathrm A_0(0,0)$，$\mathrm B_0(2,0)$，$\mathrm C_0(1,\sqrt3)$ がある．$\triangle\mathrm A_0\mathrm B_0\mathrm C_0$ の辺 $\mathrm A_0\mathrm B_0$，$\mathrm B_0\mathrm C_0$，$\mathrm C_0\mathrm A_0$ をそれぞれ $1:2$ に内分する点を $\mathrm A_1$，$\mathrm B_1$，$\mathrm C_1$ とし，同じ操作を繰り返して $\mathrm A_n$，$\mathrm B_n$，$\mathrm C_n$ を定める．
\begin{enumerate}
  \item $\angle\mathrm A_0\mathrm A_1\mathrm A_2$ の大きさと，$\mathrm A_0\mathrm A_1:\mathrm A_1\mathrm A_2$ を求めよ．
  \item 点 $\mathrm A_{6n}$ の座標を求めよ．
  \item 折れ線 $\mathrm A_0\mathrm A_1\mathrm A_2\cdots$ の長さ（$\displaystyle\sum_{k=0}^\infty\mathrm A_k\mathrm A_{k+1}$）を求めよ．
\end{enumerate}

次の方程式の解 $z$ を求めよ．(1)(2) は $a+bi$ の形で，(3) は極形式で答えよ．
\begin{enumerate}
  \item $z^3=8i$
  \item $z^4=-8+8\sqrt3\,i$
  \item $z^8-\sqrt3\,z^4+1=0$
\end{enumerate}

複素数平面上の5点 $\mathrm A_0,\dots,\mathrm A_4$ は原点を中心とする半径1の円周上に反時計回りに並んで正五角形をなし，$\mathrm A_0$ は1を表す．$\mathrm A_k$ を表す複素数を $\alpha_k$ とする．
\begin{enumerate}
  \item $\alpha_1,\alpha_2$ を，三角関数を用いない形で求めよ．
  \item 点Pが原点を中心とする半径2の円周上を動くとき，$L=\mathrm{PA_0}\cdot\mathrm{PA_1}\cdot\mathrm{PA_2}\cdot\mathrm{PA_3}\cdot\mathrm{PA_4}$ の最大値と最小値，およびそれぞれを与えるPを求めよ．
  \item (2) のPに対して，$\mathrm{PA_0}^2+\mathrm{PA_1}^2+\dots+\mathrm{PA_4}^2$ は一定であることを示し，その値を求めよ．
\end{enumerate}

$n$ を2以上の整数とし，$\alpha=\cos\dfrac{2\pi}n+i\sin\dfrac{2\pi}n$ とする．
\begin{enumerate}
  \item $\displaystyle\prod_{k=1}^{n-1}(x-\alpha^k)=1+x+x^2+\dots+x^{n-1}$ を示せ．
  \item $a=\dfrac{3+\sqrt5}2$ とする．$\displaystyle\prod_{k=1}^{n-1}\left(3-2\cos\frac{2k\pi}n\right)=a^n+a^{-n}-2$ を示せ．
  \item $n=5$ のとき，(2) の値を求めよ．
\end{enumerate}

\begin{enumerate}
  \item 3個の複素数 $1,\ z,\ z^3$ が表す点が同一直線上にあるような $z$ の条件を求め，その範囲を複素数平面上に図示せよ．
  \item $a,b,c$ を，絶対値が1である相異なる複素数とし，$h=a+b+c$ とする．A$(a)$，B$(b)$，C$(c)$，H$(h)$ について，$h\neq a$ ならば $\dfrac{h-a}{c-b}$ は純虚数であることを示せ．また，これを用いて，Hが三角形ABCの垂心であることを示せ．
\end{enumerate}

$\alpha,\beta,\gamma$ は互いに相異なる複素数とする．
\begin{enumerate}
  \item 複素数平面上で，$0<\arg\dfrac{z-\beta}{z-\alpha}<\dfrac\pi2$ となる $z$ の存在する範囲を図示せよ．
  \item $\alpha,\beta,\gamma$ が同一直線上にないとき，$(z-\alpha)(z-\beta)+(z-\beta)(z-\gamma)+(z-\gamma)(z-\alpha)=0$ をみたす $z$ は，$\alpha,\beta,\gamma$ を頂点とする三角形の内部にあることを示せ．
  \item $\alpha=0$，$\beta=6$，$\gamma=6i$ のとき，(2) の方程式の解を求めよ．
\end{enumerate}

$\omega=\dfrac{-1+\sqrt3\,i}2$ とし，複素数 $\alpha,\beta,\gamma$ を表す点を A，B，C とする．
\begin{enumerate}
  \item $\alpha^2+\beta^2+\gamma^2-\alpha\beta-\beta\gamma-\gamma\alpha=(\alpha+\omega\beta+\omega^2\gamma)(\alpha+\omega^2\beta+\omega\gamma)$ を示せ．
  \item $\alpha+\omega\beta+\omega^2\gamma=0$ ならば，A=B=C であるか，三角形ABCは正三角形であることを示せ．
  \item $\alpha=1$，$\beta=i$ のとき，三角形ABCが正三角形となる $\gamma$ をすべて求めよ．
\end{enumerate}

複素数平面上の正三角形ABCと点Pを考え，A，B，C，Pを表す複素数を $a,b,c,p$ とする．
\begin{enumerate}
  \item 恒等式 $(p-a)(b-c)+(p-b)(c-a)+(p-c)(a-b)=0$ を確かめ，$\mathrm{PC}\leqq\mathrm{PA}+\mathrm{PB}$ を証明せよ．
  \item $a=1$，$b=\omega$，$c=\omega^2$（$\omega=\frac{-1+\sqrt3i}2$）とする．(1) で等号が成り立つための必要十分条件は，Pが三角形ABCの外接円の弧ABのうちCを含まない方（両端を含む）にあることであることを証明せよ．
\end{enumerate}

単位円周上の相異なる2点 P$(\alpha)$，Q$(\beta)$ を通る直線を $l$ とし，点1から $l$ に下ろした垂線の足を R$(w)$ とする．
\begin{enumerate}
  \item $w=\dfrac{1+\alpha+\beta-\alpha\beta}2$ であることを示せ．
  \item $\alpha=i$ とし，$\beta$ が $i$ 以外の単位円周上を動くとき，点Rの軌跡を求めよ．
\end{enumerate}

\begin{enumerate}
  \item 複素数平面上で方程式 $|z-4|=3|z|$ が表す図形を求めよ．
  \item 複素数 $z$ が (1) の図形上を動くとき，$w=(1+\sqrt3\,i)z$ が表す点の軌跡を求めよ．
  \item 複素数 $z$ が (1) の図形から $z=1$ を除いた部分を動くとき，$w=\dfrac{z+2}{z-1}$ で表される点の軌跡を求めよ．
\end{enumerate}

3つの複素数 $z_1=1+i$，$z_2=1-i$，$z_3=-1$ の表す点を A，B，C とする．0でない複素数 $z$ に対し $w=\dfrac1z$ とし，$z,w$ の表す点を P，Q とする．
\begin{enumerate}
  \item Pが線分AB上を動くとき，Qの描く曲線を求めよ．
  \item Pが三角形ABCの3辺上を動くとき，Qの描く曲線を求めよ．
\end{enumerate}

複素数平面上で中心が1，半径1の円を $C$ とする．
\begin{enumerate}
  \item $C$ 上の点 $z=1+\cos t+i\sin t$（$-\pi<t<\pi$）について，$z$ の絶対値と偏角を $t$ で表し，$\dfrac1{z^2}$ を極形式で表せ．
  \item $z$ が $C$ 上の0でない点を動くとき，$w=\dfrac4{z^2}$ は放物線全体を描くことを示し，その方程式を求めよ．
  \item (2) の放物線と虚軸で囲まれた部分の面積を求めよ．
\end{enumerate}

複素数 $\alpha,\beta,\beta'$ は $|\alpha-1|=1$，$|\beta-i|=1$，$|\beta'-2i|=1$ をみたす．
\begin{enumerate}
  \item $2\alpha+\beta$ が存在する範囲を求め，図示せよ．
  \item $(\alpha-1)(\beta'-1)$ が存在する範囲を求めよ．
  \item $\alpha$ が動くとき，$\alpha^2$ が描く曲線で囲まれた部分の面積を求めよ．
\end{enumerate}

$z_1=2$，$z_{n+1}=(1+\sqrt3\,i)z_n-\sqrt3\,i$（$n\geqq1$）で定まる数列 $\{z_n\}$ について答えよ．
\begin{enumerate}
  \item $z_n$ を求めよ．
  \item すべての正の整数 $m$ について，$z_{6m+1}=64^m+1$，$z_{6m+4}=1-2^{6m+3}$ となることを示せ．
  \item $z_n$ が表す点を $\mathrm P_n$ とする．$\mathrm P_n,\mathrm P_{n+1},\mathrm P_{n+2}$ を3頂点とする三角形の面積を求めよ．
\end{enumerate}

$xy$ 平面上に原点 O を中心とする半径3の円 $C_1$ と点 A$(5,0)$ がある．A を通り $C_1$ に外接する円 $C_2$ を考え，その中心を M，半径を $r$ とする．また，AP が $C_2$ の直径となるように点 P をとる．
\begin{enumerate}
  \item M の軌跡を求めよ．
  \item P の軌跡を求め，その曲線の焦点の一つが A であることを確かめよ．
  \item $r$ の最小値を求めよ．
\end{enumerate}

\begin{enumerate}
  \item 放物線 $y^2=4x$ の焦点を F，$C$ 上の原点以外の点を P$(t^2,2t)$ とし，P における法線と $x$ 軸の交点を N とする．FP$=$FN を示し，P における接線は直線 PF と，P を通り $x$ 軸に平行な直線のなす角を2等分することを示せ．
  \item 楕円 $E:\dfrac{x^2}9+\dfrac{y^2}5=1$ と焦点を共有し，$E$ と $x$ 座標が $\frac32$ の点で交わる双曲線 $H$ を求めよ．さらに，その交点（第1象限）で $E$，$H$ の接線が直交することを確かめよ．
  \item 一般に，焦点を共有する楕円と双曲線は，その交点で接線が直交することを証明せよ．
\end{enumerate}

\begin{enumerate}
  \item 楕円 $\dfrac{x^2}4+y^2=1$ の焦点を F，F$'$，楕円上の点を P とする．PF$\cdot$PF$'$ のとり得る値の範囲と，$\angle\mathrm{FPF'}$ の最大値を求めよ．また，$\angle\mathrm{FPF'}=90^\circ$ となる P の個数と，そのときの $\triangle\mathrm{FPF'}$ の面積を求めよ．
  \item 楕円 $\dfrac{x^2}{25}+\dfrac{y^2}9=1$ 上に A$(5\cos\theta,3\sin\theta)$（$0<\theta<\frac\pi2$），B$(5,0)$ をとり，A，B における接線の交点を D，焦点 $(4,0)$ を F とする．
  \begin{enumerate}
    \item A における接線と $x$ 軸の交点 E の座標を求めよ．
    \item 直線 FD は $\angle\mathrm{AFB}$ を2等分することを示せ．
    \item AF$\perp x$ 軸のとき，D の座標と $\angle\mathrm{DFB}$ を求めよ．
  \end{enumerate}
\end{enumerate}

楕円 $\dfrac{x^2}9+\dfrac{y^2}4=1$ に内接する三角形を考える．
\begin{enumerate}
  \item 面積の最大値を求めよ．
  \item 3頂点がすべて $y\geqq0$ の部分にあるとき，面積の最大値と，それを与える三角形を求めよ．
\end{enumerate}

双曲線 $H:\dfrac{x^2}{a^2}-\dfrac{y^2}{b^2}=1$（$a>0$，$b>0$）と，$y$ 軸上の点 $(0,k)$ を中心とし $H$ とちょうど2点を共有する円 $C$ がある．
\begin{enumerate}
  \item $C$ の半径を $\rho$ とするとき，$\rho^2$ と2共有点の $y$ 座標を $a,b,k$ で表せ．
  \item $H$ の漸近線 $y=\frac bax$ が $C$ から切り取る線分の長さは，$k$ によらず $2a$ であることを示せ．
  \item $a=1$，$b=\sqrt3$ のとき，(2) の線分の一端が原点となるような $k$ を求めよ．
\end{enumerate}

点 P から放物線 $y=x^2$ に2本の接線を引き，接点を A，B とする．
\begin{enumerate}
  \item $\angle\mathrm{APB}=\dfrac\pi3$ を満たしながら P が動くとき，P の軌跡を求めよ．
  \item $\angle\mathrm{APB}=\dfrac{2\pi}3$ を満たしながら P が動くとき，P の軌跡を求めよ．
  \item (1)(2) の軌跡は1つの双曲線の2つの枝であることを示し，その双曲線の漸近線を求めよ．
\end{enumerate}

原点 O を端点とし，$x$ 軸となす角が $-\frac\pi6$，$\frac\pi6$ の半直線を $L_1$，$L_2$ とする．$L_1$ 上に P，$L_2$ 上に Q を PQ$=1$ となるようにとり（P，Q は O であってもよい），直線 PQ に関して O と反対側に，$\angle\mathrm{PRQ}=90^\circ$，RP$=$RQ となる点 R をとる．
\begin{enumerate}
  \item PQ$\perp x$ 軸のとき，R の座標を求めよ．
  \item OP$=p$，OQ$=q$ として R の座標を $p,q$ で表せ．
  \item R の軌跡は楕円の一部であることを示し，その楕円の方程式と R の動く範囲を求めよ．
\end{enumerate}

長軸の長さ $2a$，短軸の長さ $2b$ の楕円 $C$ の中心 O を通り，互いに $60^\circ$ の角をなす3直線 $L_1,L_2,L_3$ を引き，$L_i$ が $C$ から切り取る線分の長さを $l_i$ とする．
\begin{enumerate}
  \item $\dfrac1{l_1^2}+\dfrac1{l_2^2}+\dfrac1{l_3^2}$ は3直線の選び方によらず一定であることを示し，その値を $a,b$ で表せ．
  \item $a=2$，$b=1$ のとき，(1) の値を求めよ．また，$l_1l_2l_3$ は一定でないことを，具体的に2通りの値を求めて示せ．
\end{enumerate}

$0<a<1$ とする．複素数平面上で原点 $A_0$ から出発して実軸の正の向きに $a$ だけ進んだ点を $A_1$ とし，以後 $A_{n-1}$ で進行方向を反時計回りに $60^\circ$ 回転して $a^n$ だけ進んだ点を $A_n$ とする．
\begin{enumerate}
  \item 点列 $A_n$ の極限の点の座標を $a$ で表せ．
  \item $a$ が $0<a<1$ の範囲を動くとき，(1) の極限点が描く図形を求めよ．
\end{enumerate}

$(a,b)\neq(0,0)$ とし，座標平面上の点 $(x,y)$ を点 $(ax-by,\ bx+ay)$ に移す移動を $f$ とする．$f$ は直線 $\ell_1:y=2x+1$ を直線 $\ell_2:x+2y=3$ に移すとする．
\begin{enumerate}
  \item $a,b$ の値を求めよ．
  \item 点 $\mathrm P(1,2)$ が移る点を Q とするとき，2直線 OP，OQ のなす角を求めよ（O は原点）．
  \item $f$ による $\ell_2$ の像 $\ell_3$ の方程式を求めよ．
\end{enumerate}

$0<\alpha<\frac\pi2$，$r>0$ とし，$xy$ 平面で中心 $\mathrm A(r\cos\alpha,\ r\sin\alpha)$，半径 $r$ の円を $C$ とする（$C$ は原点 O を通る）．O を除く $C$ 上の点 P に対し，次の2条件で点 Q を定める．
\begin{center}
(a)\ $\overrightarrow{\mathrm{OQ}}$ の向きは，$\overrightarrow{\mathrm{OP}}$ の向きを $x$ 軸に関して折り返した向き．\qquad (b)\ $|\overrightarrow{\mathrm{OP}}||\overrightarrow{\mathrm{OQ}}|=1$．
\end{center}
\begin{enumerate}
  \item P が O を除く $C$ 上を動くとき，Q はある直線 $l$ 上の全体を動くことを示し，$l$ の方程式を求めよ．
  \item $l$ が $C$ と異なる2点で交わるための $r$ の条件を $\alpha$ で表せ．
  \item $\alpha=\frac\pi3$，$r=\sqrt2$ のとき，$l$ が $C$ から切り取る弦の長さを求めよ．
\end{enumerate}

$xy$ 平面上で，直線 $y=x$ を $l$，直線 $y=-x$ を $l'$ とする．点 $\mathrm{A}(a,b)$ は $b>|a|$ をみたす定点とする．点 A を通る直線 $m$ が，$l$ と $x$ 座標が正の点 P で交わり，$l'$ と $y$ 座標が正の点 P$'$ で交わるとする．線分 PP$'$ の中点を M とする．
\begin{enumerate}
  \item 直線 $m$ を変化させるとき，点 M の軌跡は，線分 OA の中点を通り $l,l'$ にそれぞれ平行な2直線を漸近線とする双曲線の一部であることを示せ．ただし O は原点である．
  \item $\mathrm{A}(1,3)$ のとき，点 M の軌跡を $x,y$ の方程式と範囲で表せ．
  \item $\mathrm{A}(1,3)$ のとき，三角形 OPP$'$ の面積の最小値と，そのときの P，P$'$ を求めよ．
\end{enumerate}

楕円 $E:\ \dfrac{x^2}4+y^2=1$ と直線 $\ell:\ x+y=3$ がある．$\ell$ 上の点 $\mathrm A(t,\,3-t)$ から $E$ に引いた2本の接線の接点を Q，R とする．
\begin{enumerate}
  \item 直線 QR の方程式を求めよ．また，A が $\ell$ 上を動くとき，直線 QR は定点を通ることを示し，その定点を求めよ．
  \item A が $\ell$ 上を動くとき，線分 QR の中点 M の軌跡を求めよ．
\end{enumerate}

$a>b>0$ とし，楕円 $E:\ \dfrac{x^2}{a^2}+\dfrac{y^2}{b^2}=1$ と，$E$ 上の点 $\mathrm A(0,-b)$ を考える．
\begin{enumerate}
  \item 点 B が $E$ 上を動くとき，線分 AB の長さの最大値を $a$，$b$ で表せ．また，最大値を与える B をすべて求めよ．
  \item $a=2\sqrt3$，$b=2$ のとき，(1) で最大値を与える点を $\mathrm B_1$，$\mathrm B_2$ とする．線分 $\mathrm{AB_1}$，$\mathrm{AB_2}$ と，$E$ の弧 $\mathrm B_1\mathrm B_2$ のうち A を含まない方とで囲まれた図形の面積を求めよ．
\end{enumerate}

双曲線 $C:\ \dfrac{y^2}{4}-x^2=1$ について，次の問いに答えよ．
\begin{enumerate}
  \item 直線 $y=mx+n$ が $C$ に接するための $m$，$n$ の条件を求め，そのときの接点の座標を $m$，$n$ で表せ．また，$C$ には $y$ 軸に平行な接線がないことを示せ．
  \item $C$ 上にない点 $\mathrm P(p,q)$ を通る $C$ の接線がちょうど2本あって，その2本が直交するための $p$，$q$ の条件を求めよ．
  \item (2) の条件のもとで，2つの接点がともに $C$ の同じ枝（$y>0$ の部分，または $y<0$ の部分）にあるような点 P の範囲を求めよ．
\end{enumerate}

$f(\theta)$ は実数全体で定義された正の値をとる関数で，微分可能かつ $f'(\theta)$ は連続であり，$f(0)=1$ をみたすとする．原点を極，$x$ 軸の正の部分を始線とする極方程式 $r=f(\theta)$（$\theta$ は実数全体）で表される曲線を $K$ とする．$K$ 上のどの点 P においても，直線 OP と P における $K$ の接線のなす角が $\dfrac{\pi}{3}$ であるとする．
\begin{enumerate}
  \item $f(\theta)$ をすべて求めよ．
  \item (1) の $f$ のうち増加関数であるものについて，$\theta$ が $t$ から $0$ まで動くときの $K$ の長さを $L(t)$ とする．$\displaystyle\lim_{t\to-\infty}L(t)$ を求めよ．
  \item (2) の $f$ について，$\theta$ が $0$ から $2\pi$ まで動くとき，線分 OP が通過する部分の面積を求めよ．
\end{enumerate}

楕円 $E:\ \dfrac{x^2}{4}+\dfrac{y^2}{3}=1$ の焦点 $\mathrm F(1,0)$ を通る2本の弦 AC，BD が F で直交している．ベクトル $\overrightarrow{\mathrm{FA}}$，$\overrightarrow{\mathrm{FB}}$，$\overrightarrow{\mathrm{FC}}$，$\overrightarrow{\mathrm{FD}}$ が $x$ 軸の正の方向となす角は，それぞれ $\theta$，$\theta+\dfrac{\pi}{2}$，$\theta+\pi$，$\theta+\dfrac{3\pi}{2}$ である．
\begin{enumerate}
  \item 線分 AF の長さを $\theta$ で表せ．
  \item $\dfrac{1}{\mathrm{AC}}+\dfrac{1}{\mathrm{BD}}$ は $\theta$ によらず一定であることを示し，その値を求めよ．
  \item 四角形 ABCD の面積のとりうる値の範囲を求めよ．
\end{enumerate}

双曲線 $H:\ x^2-\dfrac{y^2}{4}=1$ と，円 $C_0:\ x^2+y^2=r^2$（$r>0$）がある．4つの頂点がすべて $H$ 上にあり，4つの辺がすべて $C_0$ に接する平行四辺形を「良い平行四辺形」とよぶ．
\begin{enumerate}
  \item 良い平行四辺形が存在するような $r$ の値を求めよ．
  \item $r$ が (1) の値のとき，良い平行四辺形の頂点となりうる $H$ 上の点 $(x,y)$ の範囲を求めよ．
  \item $r$ が (1) の値のとき，良い平行四辺形の面積のとりうる値の範囲を求めよ．
\end{enumerate}

$xy$ 平面上の単位円 $C_1$ と点 $\mathrm R(2,0)$ を考える．$C_1$ 上の点 $\mathrm P(\cos t,\sin t)$ における $C_1$ の接線に R から下ろした垂線の足を Q とする．P が $C_1$ 上を1周するときに Q が描く曲線を $C_2$ とする．
\begin{enumerate}
  \item Q の座標を $t$ で表し，$C_2$ 上の点の $x$ 座標のとりうる値の範囲を求めよ．
  \item Q が R と一致するような $t$（$0\leqq t<2\pi$）を求めよ．
  \item $C_2$ は R で交わる2つのループからなる．内側のループで囲まれた部分の面積 $S_1$ と，外側のループの内部で内側のループの外部にある部分の面積 $S_2$ を求めよ．
\end{enumerate}

$i$ を虚数単位とする．次の条件 (I)，(II) をともにみたす複素数 $z$ 全体の集合を $S$ とする．
\begin{itemize}
  \item[(I)] $z$ の虚部は正である．
  \item[(II)] 複素数平面上の3点 A$(1)$，B$\bigl(1+i(z-1)\bigr)$，C$(z^2-2z)$ は一直線上にある．
\end{itemize}
\begin{enumerate}
  \item 集合 $S$ を複素数平面上に図示せよ．
  \item $w=\dfrac1z$ とする．$z$ が $S$ を動くとき，点 $w$ の描く図形 $T$ を図示せよ．
  \item $z$ が $S$ を動くとき，$\left|w+\dfrac i2\right|$ の最小値と，そのときの $z$ を求めよ．
\end{enumerate}

$n$ を正の整数，$N=2n+1$ とし，$\alpha=\cos\dfrac{2\pi}N+i\sin\dfrac{2\pi}N$ とする．
\begin{enumerate}
  \item $\displaystyle\prod_{k=1}^{2n}(1+\alpha^k)=1$ を示せ．
  \item $\displaystyle\prod_{k=1}^{n}\cos\frac{k\pi}N=\frac1{2^n}$，$\displaystyle\prod_{k=1}^{n}\sin\frac{k\pi}N=\frac{\sqrt N}{2^n}$ を示し，$\displaystyle\prod_{k=1}^{n}\tan\frac{k\pi}N$ の値を求めよ．
  \item $\displaystyle\prod_{k=1}^{n}\left(5+4\cos\frac{2k\pi}N\right)$ を $n$ で表せ．また，$n=3$ のときの値を求めよ．
\end{enumerate}

$M$ は有限個の複素数からなる空でない集合で，次の2条件をみたすとする．
\begin{itemize}
  \item[(a)] $0\notin M$
  \item[(b)] $z,w\in M$ ならば $zw\in M$
\end{itemize}
$M$ の要素の個数を $N$ とする．（$1\in M$ は仮定しない．）
\begin{enumerate}
  \item 任意の $\alpha\in M$ について，$|\alpha|=1$ であり，$\alpha^d=1$ となる自然数 $d$ が存在することを示せ．
  \item $1\in M$ であり，$\alpha\in M$ ならば $\dfrac1\alpha\in M$ であることを示せ．
  \item 任意の $\alpha\in M$ について $\alpha^N=1$ であることを示し，$M=\{z\mid z^N=1\}$ であることを示せ．
  \item $N=12$ のとき，$\alpha\in M$ であって $M=\{\alpha,\alpha^2,\dots,\alpha^{12}\}$ となるものの個数と，それらの $\alpha$ の和を求めよ．
\end{enumerate}

$m,n,p,q$ は実数で，$x$ の2次方程式 $x^2+2mx+n=0$ と $x^2+2px+q=0$ はともに実数解をもたないとする．それぞれの解を $\alpha,\beta$ および $\gamma,\delta$ とする．ただし，$\alpha$，$\gamma$ の虚部は正とする．複素数平面上で $\alpha,\beta,\gamma,\delta$ の表す点をそれぞれ A，B，C，D，原点を O とする．
\begin{enumerate}
  \item $m\neq p$ のとき，4点 A，B，C，D は同一円周上にあることを示し，その円の中心を表す複素数を $m,n,p,q$ で表せ．
  \item 三角形 OAC が $\angle\mathrm{AOC}=90^\circ$ の直角二等辺三角形となるような $p,q$ が存在するための $m$ の条件を求め，そのときの $p,q$ を $m,n$ で表せ．
  \item (2) のとき，4点 A，B，C，D を適当な順に結ぶと正方形になるための $m,n$ の条件を求めよ．
\end{enumerate}

複素数平面上の3点 A$(\alpha)$，B$(\beta)$，C$(\gamma)$ はこの順に反時計回りに三角形をなすとする．三角形 ABC の外側に，辺 BC，CA，AB をそれぞれ1辺とする正方形をつくり，それらの中心を P，Q，R とする．三角形 ABC，PQR の面積を $S$，$T$ とし，$a=\mathrm{BC}$，$b=\mathrm{CA}$，$c=\mathrm{AB}$ とする．
\begin{enumerate}
  \item P を表す複素数を $\beta,\gamma$ で表し，三角形 PQR の重心は三角形 ABC の重心と一致することを示せ．
  \item $T=S+\dfrac{a^2+b^2+c^2}8$ を示せ．
  \item 三角形 ABC をいろいろ変えるとき，$\dfrac TS$ の最小値を求めよ．また，最小となるのは三角形 ABC がどのような三角形のときか．
\end{enumerate}

複素数平面上で，原点を中心とする半径1の円を単位円という．単位円上に異なる3点 A$(\alpha)$，B$(\beta)$，C$(\gamma)$ があり，3直線 BC，CA，AB のいずれの上にもない点 P$(w)$ から直線 BC，CA，AB に下ろした垂線の足をそれぞれ A$'$，B$'$，C$'$ とする．
\begin{enumerate}
  \item 直線 AB 上の点 $z$ は $z+\alpha\beta\bar z=\alpha+\beta$ をみたすことを示し，C$'$ を表す複素数 $\gamma'$ について $2\gamma'=\alpha+\beta+w-\alpha\beta\bar w$ が成り立つことを示せ．
  \item $\alpha=1$，$\beta=\omega$，$\gamma=\omega^2$（ただし $\omega=\dfrac{-1+\sqrt3\,i}2$）のとき，三角形 A$'$B$'$C$'$ の面積（3点が一直線上にあるときは0とする）は $\dfrac{3\sqrt3}{16}\bigl||w|^2-1\bigr|$ であることを示せ．
  \item (2) のとき，三角形 A$'$B$'$C$'$ の面積が三角形 ABC の面積の $\dfrac12$ となるような点 P の全体を求めよ．
\end{enumerate}

0でない複素数 $z$ に対して $w=\dfrac1z$ とする．
\begin{enumerate}
  \item $\alpha$ を0でない複素数とする．点 $z$ が原点 O と点 $\alpha$ を結ぶ線分の垂直二等分線上を動くとき，点 $w$ は円 $\left|w-\dfrac1\alpha\right|=\dfrac1{|\alpha|}$ から原点を除いた部分全体を動くことを示せ．
  \item $n$ を3以上の整数，$\varepsilon=\cos\dfrac{2\pi}n+i\sin\dfrac{2\pi}n$ とする．点 $z$ が $1,\varepsilon,\varepsilon^2,\dots,\varepsilon^{n-1}$ を頂点とする正 $n$ 角形の周上を動くとき，点 $w$ が描く閉曲線で囲まれる部分の面積 $A_n$ を $n$ で表せ．
  \item $A_4$ の値と $\displaystyle\lim_{n\to\infty}A_n$ を求めよ．
\end{enumerate}

複素数平面上で，原点 O を中心とする半径1の円を $C$ とし，点 A$(2)$ をとる．$C$ 上の点 P$(z)$ における $C$ の接線に関して A と対称な点を Q$(u)$ とする．
\begin{enumerate}
  \item $u$ を $z$ の多項式として表せ．
  \item $1-2u=(2z-1)^2$ を示せ．また，P が $C$ 全体を動くとき，点 $s=\dfrac1{2z-1}$ はある円の周全体を動く．その円の中心と半径を求めよ．
  \item P が $C$ のうち実部が $\dfrac12$ 以上の部分を動くとき，点 $w=\dfrac1{1-2u}$ は閉曲線を描くことを示し，この閉曲線で囲まれる部分の面積を求めよ．
\end{enumerate}

媒介変数 $t$ を用いて $x=t+1,\ y=t^2-2t$ と表される曲線について，
\begin{enumerate}
  \item $t$ を消去して，$y=(x\ \text{の式})$ の形で表せ．
  \item この曲線（放物線）の頂点の座標を求めよ．
\end{enumerate}

\begin{enumerate}
  \item 極座標が $\left(2,\ \dfrac{2\pi}{3}\right)$ である点の直交座標を求めよ．
  \item 直交座標が $(1,\ -1)$ である点の極座標 $(r,\ \theta)$ を求めよ．ただし $r>0,\ 0\leqq\theta<2\pi$ とする．
\end{enumerate}

$z=\dfrac{3+i}{1-i}$ について，
\begin{enumerate}
  \item $z=a+bi$（$a,\ b$ は実数）とするとき，$a,\ b$ を求めよ．
  \item $|z|$ を求めよ．
\end{enumerate}

$z=1+\sqrt3i$ について，
\begin{enumerate}
  \item $z=r(\cos\theta+i\sin\theta)$（$r>0,\ 0\leqq\theta<2\pi$）の形で表すとき，$r,\ \theta$ を求めよ．
  \item $z^6$ を求めよ．
\end{enumerate}

複素数平面上の2点 $\mathrm{A}(1+2i),\ \mathrm{B}(4-2i)$ について，
\begin{enumerate}
  \item 2点 A，B 間の距離を求めよ．
  \item 線分 AB を $1:2$ に内分する点を表す複素数を $a+bi$（$a,\ b$ は実数）とするとき，$a,\ b$ を求めよ．
\end{enumerate}

次の点を表す複素数を $a+bi$（$a,\ b$ は実数）とするとき，$a,\ b$ を求めよ．
\begin{enumerate}
  \item 点 $3+i$ を，点 $1+i$ を中心として $\dfrac{\pi}{2}$ だけ回転した点
  \item 点 $2$ を，原点を中心として $\dfrac{\pi}{3}$ だけ回転した点
\end{enumerate}

楕円 $\dfrac{x^2}{4}+y^2=1$ と直線 $y=x+k$ について，
\begin{enumerate}
  \item 楕円と直線が接するような $k$ の値をすべて求めよ．
  \item $k>0$ のとき，接点の座標を求めよ．
\end{enumerate}

円 $C:\ x^2+y^2=1$ に外接し，直線 $\ell:\ y=-2$ に接する円（$\ell$ より上側にある）の中心を $\mathrm{P}(x,\ y)$ とする．
\begin{enumerate}
  \item P の軌跡を $y=(x\ \text{の式})$ の形で表せ．
  \item この軌跡は放物線である．その焦点の座標を求めよ．
\end{enumerate}

点 $\mathrm{A}(0,\ 2)$ から楕円 $\dfrac{x^2}{3}+y^2=1$ に引いた接線について，
\begin{enumerate}
  \item 接線の傾きをすべて求めよ．
  \item 接点の座標をすべて求めよ．
\end{enumerate}

楕円 $\dfrac{x^2}{9}+\dfrac{y^2}{4}=1$ 上の点 P と直線 $2x+3y=12$ の距離を $d$ とする．
\begin{enumerate}
  \item $d$ の最小値と，そのときの P の座標を求めよ．
  \item $d$ の最大値を求めよ．
\end{enumerate}

媒介変数 $t\ (t>0)$ を用いて $x=t+\dfrac1t,\ y=t-\dfrac1t$ と表される曲線 $C$ について，
\begin{enumerate}
  \item $x^2-y^2$ の値を求めよ．
  \item $C$ 上の点の $x$ 座標のとりうる値の範囲を求めよ．
\end{enumerate}

極方程式 $r\cos\left(\theta-\dfrac{\pi}{3}\right)=2$ で表される図形を $\ell$ とする．
\begin{enumerate}
  \item $\ell$ を直交座標の方程式 $y=(x\ \text{の式})$ で表せ．
  \item 原点から $\ell$ に下ろした垂線の足の直交座標を求めよ．
\end{enumerate}

極方程式 $r=\dfrac{3}{2-\cos\theta}$ で表される曲線を $C$ とする．
\begin{enumerate}
  \item $C$ を直交座標で表すと $\dfrac{(x-p)^2}{a^2}+\dfrac{y^2}{b^2}=1$ の形になる．$p,\ a^2,\ b^2$ を求めよ．
  \item $C$ の焦点の座標をすべて求めよ．
\end{enumerate}

極座標で表された2点 $\mathrm{A}\left(2,\ \dfrac\pi6\right),\ \mathrm{B}\left(4,\ \dfrac\pi2\right)$ と極 O について，
\begin{enumerate}
  \item 線分 AB の長さを求めよ．
  \item $\triangle\mathrm{OAB}$ の面積を求めよ．
\end{enumerate}

方程式 $z^3=8i$ について，
\begin{enumerate}
  \item 解を $z=r(\cos\theta+i\sin\theta)$（$r>0,\ 0\leqq\theta<2\pi$）と表すとき，$r$ と $\theta$ をすべて求めよ．
  \item 3つの解を表す点を頂点とする三角形の面積を求めよ．
\end{enumerate}

$z=\dfrac{\sqrt3+i}{1+i}$ について，
\begin{enumerate}
  \item $|z|$ と，$z$ の偏角 $\theta$（$-\pi<\theta\leqq\pi$）を求めよ．
  \item $z^n$ が正の実数となる最小の正の整数 $n$ を求めよ．
\end{enumerate}

複素数 $z$ が $|z-3|=2|z|$ を満たすとき，
\begin{enumerate}
  \item 点 $z$ 全体が表す円の中心（複素数）と半径を求めよ．
  \item $|z-i|$ の最大値と最小値を求めよ．
\end{enumerate}

点 $z$ が円 $|z-1|=1$ 上を動くとき，$w=(1+i)z$ で表される点 $w$ について，
\begin{enumerate}
  \item 点 $w$ が描く円の中心を $a+bi$（$a,\ b$ は実数）とするとき $a,\ b$ を求めよ．また，その円の半径を求めよ．
  \item $|w|$ の最大値を求めよ．
\end{enumerate}

虚数 $z$（実数でない複素数）について，$z+\dfrac4z$ が実数であるとする．
\begin{enumerate}
  \item $|z|$ を求めよ．
  \item さらに $z+\dfrac4z=2$ のとき，$z=x+yi$（$x,\ y$ は実数）として $x,\ y$ を求めよ．
\end{enumerate}

複素数平面上の3点 $\mathrm{A}(1+i),\ \mathrm{B}(4+2i),\ \mathrm{C}(3+5i)$ について，
\begin{enumerate}
  \item $\dfrac{\gamma-\alpha}{\beta-\alpha}$（$\alpha=1+i,\ \beta=4+2i,\ \gamma=3+5i$）を $a+bi$（$a,\ b$ は実数）の形にしたときの $a,\ b$ を求めよ．
  \item $\angle\mathrm{BAC}$ を求めよ．
  \item $\triangle\mathrm{ABC}$ の面積を求めよ．
\end{enumerate}
